LGS.addMeb({
 "mebi-din-y01-1": {
  "t": "din-kader",
  "a": "C",
  "o": 100000,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li><b>Kaza:</b> Allah’ın takdir ettiği olayların zamanı geldiğinde gerçekleşmesi.</li></ul><b>İstenen</b><p>Kaza kavramına örnek olan durum.</p></div><ol class=\"sv-s\"><li><b>Kader ile kazayı ayır</b> Kader, bir şeyin özelliklerinin ve yasalarının önceden belirlenmesidir (plan). Kaza, bu planın zamanı ve yeri gelince <b>olaya dönüşmesidir</b> (gerçekleşme).</li><li><b>Şıklarda “olay” arayın</b> Bir özelliğe sahip olmak ya da bir kuralın belirlenmesi kader örneğidir. Cismin yere düşmesi ise yer çekimi yasasına göre gerçekleşen bir olaydır → kaza.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Kaldırma kuvvetine sahip olmak suya verilmiş bir özelliktir → kader.</td></tr><tr><td>B</td><td>Kaynama kuralının belirlenmesi takdirdir → kader.</td></tr><tr class=\"ok\"><td>C</td><td>Yer çekimi takdirinin bir olay olarak gerçekleşmesi → kaza.</td></tr><tr><td>D</td><td>Yörüngelerin “takdir edilmesi” kaderdir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Belirlenmesi, sahip olması, takdir edilmesi” → kader; “düşmesi, doğması, gerçekleşmesi” → kaza.</div><div class=\"sv-w\"><b>Tuzak:</b> D’de gezegenlerin hareketi geçiyor ama şık hareketin “takdir edilmesini” anlatıyor; bu kaderdir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 1. soru"
 },
 "mebi-din-y01-2": {
  "t": "din-kader",
  "a": "C",
  "o": 100001,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Şüphesiz biz her şeyi bir ölçüye göre yarattık.” (Kamer, 49)</li></ul><b>İstenen</b><p>Ayetten ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Ayetin anahtar sözcüğünü bul</b> “Bir ölçüye göre yarattık” ifadesi evrende rastgelelik olmadığını, her şeyin belli bir ölçü, düzen ve plan içinde var edildiğini anlatır.</li><li><b>Şıkları ayetle karşılaştır</b> Ayette varlıkların Allah tarafından yaratıldığı söyleniyor; kendiliğinden oluşum ya da bağımsız, düzensiz olaylar fikri ayete terstir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ayet “biz yarattık” diyor; kendiliğinden oluşum ayete ters.</td></tr><tr><td>B</td><td>Belirleyici olan Allah’ın koyduğu ölçüdür; doğal süreçler tek başına değil.</td></tr><tr class=\"ok\"><td>C</td><td>“Ölçüye göre yaratma” = olaylar belli bir düzen içinde gerçekleşir.</td></tr><tr><td>D</td><td>Ölçü ve düzen, olayların birbirine bağlı ve uyumlu olduğunu gösterir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ölçü, denge, düzen ayetlerinin ortak mesajı: Evrende tesadüf yoktur.</div><div class=\"sv-w\"><b>Tuzak:</b> A, B ve D “tesadüf” fikrini farklı sözlerle anlatır; üçü de aynı nedenle elenir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 2. soru"
 },
 "mebi-din-y01-3": {
  "t": "din-kader",
  "a": "B",
  "o": 100002,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Kader ve kazaya iman, imanın esaslarındandır.</li></ul><b>İstenen</b><p>Kadere iman eden kişinin kabul ettiği yargı.</p></div><ol class=\"sv-s\"><li><b>Kadere imanın içeriğini hatırla</b> Kadere iman; Allah’ın her şeyi bildiğine, dilediğine, takdir ettiğine ve yarattığına inanmaktır. Temeli Allah’ın sonsuz <b>ilmidir</b>.</li><li><b>İrade ve sorumluluğu unutma</b> İslam’a göre insan iradesiyle seçer ve seçimlerinden sorumludur. Allah’ın bilmesi insanı zorlamaz.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İnsan davranışlarının önceden belirlenmiş olduğu düşüncesi iradeyi yok sayar.</td></tr><tr class=\"ok\"><td>B</td><td>Allah’ın bilgisi her şeyi kuşatır; kadere imanın temelidir.</td></tr><tr><td>C</td><td>İnsan iradesiyle yaptıklarından sorumludur.</td></tr><tr><td>D</td><td>İnsanın iradesiyle yaptığı seçimler de başına gelenleri etkiler.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kader = Allah’ın bilmesi ve planlaması; insanı zorlamak değil.</div><div class=\"sv-w\"><b>Tuzak:</b> A şıkkı “her şey yazılmış, elimde değil” yanlış kader anlayışıdır; LGS bunu sık çeldirici yapar.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 3. soru"
 },
 "mebi-din-y01-4": {
  "t": "din-kader",
  "a": "A",
  "o": 100003,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Kaza” sözcüğünün sözlük anlamları soruluyor.</li></ul><b>İstenen</b><p>Kazanın sözlük anlamlarından biri olmayan.</p></div><ol class=\"sv-s\"><li><b>Sözlük anlamlarını hatırla</b> Kaza: hükmetmek, emretmek, yaratmak, yerine getirmek, gerçekleştirmek.</li><li><b>Kaderin anlamıyla karıştırma</b> “Ölçüyle yapmak, ölçü, plan, takdir etmek” <b>kader</b> sözcüğünün anlamlarıdır.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Ölçüyle yapmak → kaderin anlamı, kazanın değil.</td></tr><tr><td>B</td><td>Hükmetmek → kazanın anlamı.</td></tr><tr><td>C</td><td>Emretmek → kazanın anlamı.</td></tr><tr><td>D</td><td>Yaratmak → kazanın anlamı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kader = ölçü, plan; kaza = hüküm, gerçekleştirme.</div><div class=\"sv-w\"><b>Tuzak:</b> “değildir” vurgusunu kaçırma; üç şık doğru anlamdır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 4. soru"
 },
 "mebi-din-y01-5": {
  "t": "din-kader",
  "a": "A",
  "o": 100004,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Canlıların doğması, büyümesi, çoğalması gibi olaylar.</li></ul><b>İstenen</b><p>Bu olayları açıklayan yasa türü.</p></div><ol class=\"sv-s\"><li><b>Yasa türlerini eşleştir</b> Fiziksel yasa: madde ve enerji. <b>Biyolojik yasa: canlıların yapısı, beslenmesi, büyümesi, üremesi.</b> Toplumsal yasa: insanlar ve toplumlar arası ilişkiler.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Doğma, büyüme, çoğalma canlılara ait → biyolojik.</td></tr><tr><td>B</td><td>“Ahlaki yasa” evrendeki yasalar arasında bu tür olayları açıklayan grup değildir.</td></tr><tr><td>C</td><td>Fiziksel yasa cansız madde ve enerjiyle ilgilidir.</td></tr><tr><td>D</td><td>Toplumsal yasa toplum hayatıyla ilgilidir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Canlı” sözcüğü görünce biyolojik yasayı düşün.</div><div class=\"sv-w\"><b>Tuzak:</b> B kulağa tanıdık gelir ama ders kitabındaki üç yasa fiziksel, biyolojik ve toplumsaldır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 5. soru"
 },
 "mebi-din-y01-6": {
  "t": "din-kader",
  "a": "D",
  "o": 100005,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Adalet, doğruluk ve yardımlaşmanın korunması insanların huzurunu sağlar.</li></ul><b>İstenen</b><p>Bu durumun açıklandığı kavram.</p></div><ol class=\"sv-s\"><li><b>İpucu sözcükleri bul</b> Adalet, doğruluk, yardımlaşma ve huzur; insanların bir arada yaşamasıyla ilgilidir.</li><li><b>Yasa türüne karar ver</b> İnsanlar arası ilişkileri ve toplumun ayakta kalmasını açıklayan yasalar <b>toplumsal yasalardır</b>.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğa olayları cansız doğayla ilgilidir.</td></tr><tr><td>B</td><td>Fiziksel yasalar madde ve enerjiyle ilgilidir.</td></tr><tr><td>C</td><td>Biyolojik yasalar canlıların yapısıyla ilgilidir.</td></tr><tr class=\"ok\"><td>D</td><td>Adalet ve yardımlaşma toplumsal yasalarla açıklanır.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Değer sözcükleri (adalet, güven, yardımlaşma) → toplumsal yasa.</div><div class=\"sv-w\"><b>Tuzak:</b> Huzur insanın iç dünyasıyla ilgili gibi görünse de burada toplum düzeninden söz ediliyor.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 6. soru"
 },
 "mebi-din-y01-7": {
  "t": "din-kader",
  "a": "B",
  "o": 100006,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“O, geceyi size bir örtü, uykuyu istirahat zamanı ve gündüzü de hareket ve çalışma vakti yapandır.” (Furkan, 47)</li></ul><b>İstenen</b><p>Ayette vurgulanan <b>temel</b> husus.</p></div><ol class=\"sv-s\"><li><b>Ayetin bütününe bak</b> Ayet gece ve gündüzü Allah’ın belli bir amaçla, belli bir düzen içinde yarattığını anlatır: gece dinlenme, gündüz çalışma için.</li><li><b>Ayrıntı ile temel fikri ayır</b> Dinlenme, çalışma, denge ayetteki ayrıntılardır; hepsini kapsayan ana mesaj gece ve gündüzün ölçülü ve düzenli yaratılmasıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ayetten çıkar ama yalnızca bir sonuçtur, temel vurgu değildir.</td></tr><tr class=\"ok\"><td>B</td><td>Gece ve gündüz bir ölçü ve düzenle yaratılmıştır → ayetin ana mesajı.</td></tr><tr><td>C</td><td>Ayetteki bir ayrıntı (gece dinlenme).</td></tr><tr><td>D</td><td>Ayetten yorumlanabilir ama ayet doğrudan Allah’ın düzenini vurgular.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Temel husus” sorularında ayrıntıları kapsayan en geniş yargıyı seç.</div><div class=\"sv-w\"><b>Tuzak:</b> C ve D ayette geçen ayrıntılara dayandığı için doğru görünür; ama soru ana fikri istiyor.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 7. soru"
 },
 "mebi-din-y01-8": {
  "t": "din-kader",
  "a": "A",
  "o": 100007,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Sünnetullah” kavramının anlamı soruluyor.</li></ul><b>İstenen</b><p>Sünnetullahın anlamı.</p></div><ol class=\"sv-s\"><li><b>Kavramı çöz</b> Sünnet “yol, yöntem, kanun”; Allah “Allah’ın”. Sünnetullah = <b>Allah’ın evrene koyduğu yasalar</b>, Allah’ın değişmeyen kanunları.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Allah’ın evrende koyduğu yasalar → doğru tanım.</td></tr><tr><td>B</td><td>Toplumsal kurallar insanların koyduğu kurallardır.</td></tr><tr><td>C</td><td>Peygamberin söz ve fiilleri “sünnet”tir, sünnetullah değil.</td></tr><tr><td>D</td><td>Gelenek ve görenekler toplumun kültürüdür.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Sünnetullah = âdetullah = evrendeki fiziksel, biyolojik, toplumsal yasalar.</div><div class=\"sv-w\"><b>Tuzak:</b> C’deki “sünnet” sözcüğü tuzaktır; Peygamber’in sünneti başka kavramdır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 8. soru"
 },
 "mebi-din-y01-9": {
  "t": "din-kader",
  "a": "D",
  "o": 100008,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Ey iman edenler! Allah için hakkı ayakta tutun, adaletle şahitlik eden kimseler olun…” (Maide, 8)</li></ul><b>İstenen</b><p>Ayetin ilişkili olduğu yasa türü.</p></div><ol class=\"sv-s\"><li><b>Ayetin konusunu belirle</b> Ayet adaleti ve doğru şahitliği emreder; bunlar insanlar arasındaki ilişkileri düzenler.</li><li><b>Yasa türüne karar ver</b> Toplumun huzurunu ve devamını sağlayan adalet gibi ilkeler toplumsal yasalarla ilgilidir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğa yasası cansız doğa olaylarıyla ilgilidir.</td></tr><tr><td>B</td><td>Fiziksel yasa madde ve hareketle ilgilidir.</td></tr><tr><td>C</td><td>Biyolojik yasa canlıların yapısıyla ilgilidir.</td></tr><tr class=\"ok\"><td>D</td><td>Adalet ve doğru şahitlik → toplumsal yasa.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Adalet ayetleri = toplumsal yasa.</div><div class=\"sv-w\"><b>Tuzak:</b> Ayetteki “Allah için” ifadesi dinî bir konu sanılsa da sorulan yasa türü toplumsal düzenle ilgilidir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 9. soru"
 },
 "mebi-din-y01-10": {
  "t": "din-kader",
  "a": "B",
  "o": 100009,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Arıların kilometrelerce dolaşması, kusursuz petek örmesi ve şifalı bal üretmesi yaratılış sanatının örneği olarak veriliyor.</li></ul><b>İstenen</b><p>Bu durumun göstergesi olduğu yargı.</p></div><ol class=\"sv-s\"><li><b>Örneğin vurgusunu bul</b> “Kusursuz mimari”, “yaratılış sanatı” ifadeleri arının davranışlarındaki düzenin rastgele olmadığını, bir <b>plan ve ölçüyle</b> yaratıldığını anlatır.</li><li><b>Şıkları ele</b> Kendi kendine işleyen evren fikri metne terstir; A ve C metnin vurgusu değildir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Arının doğadan yararlanması doğru ama metnin vurgusu yaratılıştaki mükemmellik.</td></tr><tr class=\"ok\"><td>B</td><td>Her şeyin belirli bir ölçü ve mükemmel planla yaratılması → metnin vurgusu.</td></tr><tr><td>C</td><td>Metinde doğanın döngü kurmasından söz edilmez; arının yaratılışı anlatılır.</td></tr><tr><td>D</td><td>Metin “yaratılış sanatı” diyor; dış müdahalesiz işleyen evren fikri ters.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kusursuz, mükemmel, yaratılış sanatı” → ölçü, düzen ve plan.</div><div class=\"sv-w\"><b>Tuzak:</b> A ilk bakışta doğru bir bilgi gibi durur ama metnin ana fikri değildir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 10. soru"
 },
 "mebi-din-y01-11": {
  "t": "din-kader",
  "a": "C",
  "o": 100010,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li><b>Kader:</b> Allah’ın her şeyi bilip takdir etmesi. <b>Kaza:</b> Zamanı gelince bu takdirin gerçekleşmesi.</li></ul><b>İstenen</b><p>Kader kavramına örnek olan durum.</p></div><ol class=\"sv-s\"><li><b>Özellik mi, olay mı?</b> Bir varlığa verilmiş özellik veya kural kaderdir. O özelliğe göre yaşanan olay kazadır.</li><li><b>Şıkları sınıflandır</b> Gemilerin yüzmesi, insanın doğması, tohumun filizlenmesi gerçekleşen olaylardır → kaza. Suyun 100 °C’de kaynama özelliğine sahip olması ise belirlenmiş bir özelliktir → kader.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Geminin yol alması gerçekleşen bir olay → kaza.</td></tr><tr><td>B</td><td>Belirlenen vakitte doğmak takdirin gerçekleşmesi → kaza.</td></tr><tr class=\"ok\"><td>C</td><td>Suyun kaynama özelliğine sahip olması → kader.</td></tr><tr><td>D</td><td>Tohumun filizlenmesi gerçekleşen bir olay → kaza.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Özelliğine sahip olması” kalıbı kaderi gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> B’deki “belirlenen vakit” ifadesi kader çağrıştırır; ama şık doğumun gerçekleşmesini anlatıyor.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 11. soru"
 },
 "mebi-din-y01-12": {
  "t": "din-kader",
  "a": "C",
  "o": 100011,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Evrendeki yasalarla olayların eşleştirmeleri verilmiş.</li></ul><b>İstenen</b><p>Yanlış eşleştirme.</p></div><ol class=\"sv-s\"><li><b>Her olayın türünü kontrol et</b> Metallerin genleşmesi madde ile ilgilidir → fiziksel. Kış uykusu canlıyla ilgilidir → biyolojik. Gelir dağılımındaki adaletsizlik toplumu ilgilendirir → toplumsal.</li><li><b>Toplumların eceli</b> Kur’an’a göre toplumların da yükselişi ve çöküşü bir süreye bağlıdır; bu, <b>toplumsal yasadır</b>.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Genleşme fiziksel yasa → doğru eşleşme.</td></tr><tr><td>B</td><td>Kış uykusu biyolojik yasa → doğru eşleşme.</td></tr><tr class=\"ok\"><td>C</td><td>Toplumların eceli toplumsal yasadır; biyolojik denmesi yanlış.</td></tr><tr><td>D</td><td>Adaletsizlik ve yoksulluk toplumsal yasa → doğru eşleşme.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Canlı bir varlık değil de <b>toplum</b> söz konusuysa yasa toplumsaldır.</div><div class=\"sv-w\"><b>Tuzak:</b> “Fertler gibi ecel” benzetmesi biyolojik yasa sandırabilir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 12. soru"
 },
 "mebi-din-y01-13": {
  "t": "din-kader",
  "a": "D",
  "o": 100012,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Adaletin olmadığı, güvenin kaybolduğu ortamda huzur ve barış bozuluyor.</li></ul><b>İstenen</b><p>Bu durumun gösterdiği sonuç.</p></div><ol class=\"sv-s\"><li><b>Sebep–sonuç ilişkisini kur</b> Adalet ve güven toplumsal yasaların gereğidir. Bu yasalara uyulmazsa toplumun huzuru bozulur.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Biyolojik yasalar değişmez; konu canlıların yapısı da değil.</td></tr><tr><td>B</td><td>Fiziksel yasalar madde ve enerjiyle ilgilidir.</td></tr><tr><td>C</td><td>Kader inancı insanların davranışıyla ortadan kalkmaz.</td></tr><tr class=\"ok\"><td>D</td><td>Adalet ve güvenin yok olması toplumsal yasaların çiğnendiğini gösterir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Toplumsal yasaya uymamanın bedelini toplum öder: huzursuzluk, çöküş.</div><div class=\"sv-w\"><b>Tuzak:</b> Evrendeki yasalar değişmez; “değişti” diyen şıklar (A) baştan elenir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 13. soru"
 },
 "mebi-din-y01-14": {
  "t": "din-kader",
  "a": "C",
  "o": 100013,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li><b>Kader:</b> Allah’ın sonsuz ilmi ve kudretiyle evrende gerçekleşecek her şeyi takdir etmesi.</li></ul><b>İstenen</b><p>Kaderin oluşumuyla ilgili söylenemeyecek yargı.</p></div><ol class=\"sv-s\"><li><b>Tanımdaki öğeleri çıkar</b> Tanımda ilim (önceden bilme), kudret (her şeye gücünün yetmesi) ve takdir (plan, düzen) var.</li><li><b>Kazayı ayır</b> “Olayların yeri ve zamanı geldiğinde gerçekleşmesi” kaderin değil, <b>kazanın</b> tanımıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Kudret → kader tanımında var.</td></tr><tr><td>B</td><td>İlim → kader tanımında var.</td></tr><tr class=\"ok\"><td>C</td><td>Gerçekleşme kazadır; kaderin oluşumu için söylenemez.</td></tr><tr><td>D</td><td>Plan ve düzen → takdir, kaderdir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Bil + planla = kader; gerçekleştir = kaza.</div><div class=\"sv-w\"><b>Tuzak:</b> C doğru bir bilgidir ama kaza kavramına aittir; soru kaderin oluşumunu soruyor.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 14. soru"
 },
 "mebi-din-y01-15": {
  "t": "din-kader",
  "a": "B",
  "o": 100014,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Cibril hadisinde Hz. Peygamber imanın esaslarını sayıyor.</li></ul><b>İstenen</b><p>Bu konuşmada kadere imanla ilgili açıklama.</p></div><ol class=\"sv-s\"><li><b>Hadisi hatırla</b> Hz. Peygamber imanı şöyle açıklar: Allah’a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe ve <b>kadere, hayrı ve şerriyle</b>, inanmak.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğru bir yargıdır ama hadisteki ifade değildir.</td></tr><tr class=\"ok\"><td>B</td><td>“Hayrı ve şerriyle kadere inanmak” hadisteki açıklama.</td></tr><tr><td>C</td><td>Allah’ın her şeyi bilmesi doğrudur ama hadiste kader böyle açıklanmaz.</td></tr><tr><td>D</td><td>Kıyamet ahirete imanla ilgilidir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Cibril hadisi = imanın altı esası; kader “hayrı ve şerriyle” kalıbıyla geçer.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve C kaderle ilgili doğru cümlelerdir; soru “bu konuşmada verilen açıklamayı” istiyor.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 15. soru"
 },
 "mebi-din-y01-16": {
  "t": "din-kader",
  "a": "D",
  "o": 100015,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Kader” kavramıyla ilişkili kelime grubu soruluyor.</li></ul><b>İstenen</b><p>Kaderle doğrudan ilişkili grup.</p></div><ol class=\"sv-s\"><li><b>Kader ve kazanın anlamlarını ayır</b> Kader: ölçü, plan, düzen, takdir etmek. Kaza: hükmetmek, yaratmak, yerine getirmek, gerçekleştirmek.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Gerçekleştirmek, yerine getirmek → kaza.</td></tr><tr><td>B</td><td>Ortaya çıkarmak, yaratmak → kaza.</td></tr><tr><td>C</td><td>Yaratmak, hükmetmek → kaza.</td></tr><tr class=\"ok\"><td>D</td><td>Plan, ölçü, düzen → kader.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ölçü–plan–düzen üçlüsü kaderin anahtar sözcükleridir.</div><div class=\"sv-w\"><b>Tuzak:</b> “Yaratmak” kaderle ilgili sanılır; sözlükte kazanın anlamıdır.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 16. soru"
 },
 "mebi-din-y01-17": {
  "t": "din-kader",
  "a": "C",
  "o": 100016,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Allah’ın her şeyi dilediği gibi var veya yok etmesi” anlamı veriliyor.</li></ul><b>İstenen</b><p>Bu anlamdaki sıfat.</p></div><ol class=\"sv-s\"><li><b>Sıfatları hatırla</b> İlim: her şeyi bilmesi. <b>İrade: dilemesi, istediğini istediği gibi yapması.</b> Kudret: gücünün her şeye yetmesi. Beka: varlığının sonu olmaması.</li><li><b>Anahtar sözcük</b> Tanımdaki “dilediği gibi” ifadesi doğrudan irade sıfatını gösterir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Beka, sonu olmamaktır.</td></tr><tr><td>B</td><td>İlim, bilmektir.</td></tr><tr class=\"ok\"><td>C</td><td>İrade, dilediği gibi yapmaktır.</td></tr><tr><td>D</td><td>Kudret, güç yetirmektir; “dilediği gibi” vurgusu iradeye aittir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Dilemek = irade, bilmek = ilim, güç = kudret.</div><div class=\"sv-w\"><b>Tuzak:</b> “Var etmek” güç gerektirdiği için kudret çeldiricidir; belirleyici sözcük “dilediği gibi”dir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 17. soru"
 },
 "mebi-din-y01-18": {
  "t": "din-kader",
  "a": "B",
  "o": 100017,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li><b>Kader:</b> Allah’ın evrende gerçekleşecek her şeyi belirli özellikleriyle takdir etmesi.</li></ul><b>İstenen</b><p>Kaderin tanımında vurgulanan iki sıfat.</p></div><ol class=\"sv-s\"><li><b>Takdir etmek neyi gerektirir?</b> Her şeyi önceden bilmek (<b>ilim</b>) ve her şeye gücü yetip planlamak (<b>kudret</b>). Ders kitabındaki tanım da “sonsuz ilmi ve kudretiyle” diye verilir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Semi (işitme) tanımla ilgili değil.</td></tr><tr class=\"ok\"><td>B</td><td>İlim ve kudret → kaderin tanımındaki iki sıfat.</td></tr><tr><td>C</td><td>Semi tanımla ilgili değil.</td></tr><tr><td>D</td><td>Kudret var ama ilim eksik; takdirin temeli bilgidir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kader tanımı: “Allah’ın sonsuz ilmi ve kudretiyle her şeyi takdir etmesi.”</div><div class=\"sv-w\"><b>Tuzak:</b> İrade de akla gelir; ama takdir etmenin temeli bilmektir, bu yüzden ilim olmayan şık eksik kalır.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 18. soru"
 },
 "mebi-din-y01-19": {
  "t": "din-kader",
  "a": "D",
  "o": 100018,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Evrendeki varlıklar uyumlu bir bütünlük içinde, belirli yasalarla hareket eder; bu ilahi ölçü ve planın sonucudur.</li></ul><b>İstenen</b><p>Evrendeki ölçü ve düzene örnek.</p></div><ol class=\"sv-s\"><li><b>Düzen ne demek?</b> Belirli, değişmeyen, önceden bilinen işleyiş. Gezegenlerin kendi yörüngelerinde hareketi bunun en açık örneğidir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Gün içi hava değişimleri değişkenliği anlatır, düzen vurgusu taşımaz.</td></tr><tr><td>B</td><td>Türlerin farklılaşması düzen örneği olarak verilmez.</td></tr><tr><td>C</td><td>İnsanların farklı yorumları evrendeki düzenle ilgili değildir.</td></tr><tr class=\"ok\"><td>D</td><td>Gök cisimlerinin belirlenmiş yörüngelerde hareketi → ölçü ve düzen.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ölçü–düzen sorularında gezegenler, gece-gündüz, mevsimler klasik örneklerdir.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve B doğa olayıdır; ama “değişim” vurgusu düzen örneği değildir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 19. soru"
 },
 "mebi-din-y01-20": {
  "t": "din-kader",
  "a": "A",
  "o": 100019,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Fiziksel yasaya örnek isteniyor.</li></ul><b>İstenen</b><p>Fiziksel yasaya örnek.</p></div><ol class=\"sv-s\"><li><b>Fiziksel yasa</b> Madde ve enerjinin hareketiyle ilgili yasalar: buharlaşma, kaynama, yer çekimi, kaldırma kuvveti.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Suyun buharlaşması → fiziksel.</td></tr><tr><td>B</td><td>Yardımlaşma → toplumsal.</td></tr><tr><td>C</td><td>Fotosentez → biyolojik (canlı).</td></tr><tr><td>D</td><td>Adaletli davranmak → toplumsal.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Cansız madde + hal değişimi → fiziksel yasa.</div><div class=\"sv-w\"><b>Tuzak:</b> Fotosentezde güneş ışığı ve su geçse de bir canlı süreci olduğu için biyolojiktir.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 20. soru"
 },
 "mebi-din-y01-21": {
  "t": "din-kader",
  "a": "A",
  "o": 100020,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Biyolojik yasaya örnek isteniyor.</li></ul><b>İstenen</b><p>Biyolojik yasaya örnek olan olay.</p></div><ol class=\"sv-s\"><li><b>Biyolojik yasa</b> Canlıların yapısı, beslenmesi, büyümesi ve üremesiyle ilgili yasalar.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Fotosentezle besin üretmek bir canlı sürecidir → biyolojik.</td></tr><tr><td>B</td><td>Kaldırma kuvveti → fiziksel.</td></tr><tr><td>C</td><td>Gezegenlerin hareketi → fiziksel.</td></tr><tr><td>D</td><td>Yoğunlaşma ve yağmur → fiziksel.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Olayın öznesi canlıysa biyolojik yasa.</div><div class=\"sv-w\"><b>Tuzak:</b> D’de doğa olayı var ama canlı yok; fiziksel yasadır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 1 · 21. soru"
 },
 "mebi-din-y02-1": {
  "t": "din-kader",
  "a": "A",
  "o": 100021,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsan bazı konularda seçme ve yönlendirme imkânına sahiptir.</li><li>Doğum yeri, dış görünüş gibi bazı özellikler insanın kontrolü dışında belirlenir.</li><li>Bu ayrım insanın hangi konularda sorumlu tutulacağını anlamaya yardım eder.</li></ul><b>İstenen</b><p>Metinden <b>ulaşılamayacak</b> yargı.</p></div><ol class=\"sv-s\"><li><b>Metnin ana fikri</b> Sorumluluk, insanın iradesiyle seçebildiği alanlarla sınırlıdır; iradesi dışında belirlenenlerden sorumlu değildir.</li><li><b>Şıkları metinle karşılaştır</b> B, C ve D bu fikrin farklı söyleyişleridir. A ise iradesi dışındaki özelliklerin çabayla değiştirilebileceğini söylüyor; metinde böyle bir bilgi yok, metin bunları “kontrol dışı” sayıyor.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Metin bu özellikleri kontrol dışı sayıyor; değiştirilebileceği söylenmiyor → ulaşılamaz.</td></tr><tr><td>B</td><td>Sorumluluk iradeyle müdahale edilebilen alanla sınırlı → ulaşılır.</td></tr><tr><td>C</td><td>Doğum yeri ve fiziksel özellikler yükümlülük dışı → ulaşılır.</td></tr><tr><td>D</td><td>Yükümlülük imkânlarla bağlantılı → ulaşılır.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Ulaşılamaz” sorularında metinde hiç geçmeyen ya da metne ters düşen yargıyı ara.</div><div class=\"sv-w\"><b>Tuzak:</b> A’daki “çaba göstermek” olumlu bir değer olduğu için doğru sanılabilir; ama metnin söylediği bu değil.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 1. soru"
 },
 "mebi-din-y02-2": {
  "t": "din-kader",
  "a": "D",
  "o": 100022,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Fatih düşük not alınca “Kaderimde böyle yazılmış, benim elimde değil.” deyip çalışmayı bırakıyor.</li><li>Öğretmeni eksiklerini belirleyip yöntem değiştirirse daha iyi sonuç alacağını söylüyor.</li></ul><b>İstenen</b><p>Fatih’in hatalı tutumunu en iyi açıklayan ifade.</p></div><ol class=\"sv-s\"><li><b>Fatih ne yapıyor?</b> Başarısızlığın sebebini kendi çabasında değil, kaderde arıyor; yani <b>sorumluluğu üstünden atıp dış bir gerekçeye bağlıyor</b>.</li><li><b>Doğru kader anlayışı</b> İnsan iradesiyle yaptığı seçimlerden sorumludur; kaderi bahane etmek yanlıştır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Bu öğretmenin tutumudur; Fatih sonucu çalışmaya bağlamıyor.</td></tr><tr><td>B</td><td>Fatih kendini yetersiz saymıyor, suçu kadere atıyor.</td></tr><tr><td>C</td><td>Metinde kısa sürede sonuç beklemekten söz edilmiyor.</td></tr><tr class=\"ok\"><td>D</td><td>Kendi payını görmezden gelip sorumluluğu kadere yüklüyor → doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kaderimde varmış” diye çabayı bırakmak = sorumluluğu kadere yüklemek.</div><div class=\"sv-w\"><b>Tuzak:</b> B’de de çabadan vazgeçme var; ama Fatih’in gerekçesi “yetersizim” değil, “kaderim”.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 2. soru"
 },
 "mebi-din-y02-3": {
  "t": "din-kader",
  "a": "A",
  "o": 100023,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Allah’ın ilmi görünen ve görünmeyeni kuşatır.</li><li>İnsanın bilgisi ve gücü sınırlıdır; bu sınırlılık insan davranışlarının değerlendirilmesinde dikkate alınır.</li></ul><b>İstenen</b><p>Metinden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Son cümleye odaklan</b> İnsanın sınırlılığı “dikkate alınıyorsa” insan gücünün yetmediği şeyden sorumlu tutulmaz. Yani yükümlülükler insanın imkânına göre belirlenir.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Sınırlılık değerlendirmede dikkate alınır → yükümlülük imkâna göre → ulaşılır.</td></tr><tr><td>B</td><td>Doğru bir bilgi ama metinde öğrenmeden söz edilmez.</td></tr><tr><td>C</td><td>Akılla tercih metinde geçmez.</td></tr><tr><td>D</td><td>Allah’ın varlığını akılla temellendirme metnin konusu değildir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Bakara 286: “Allah kimseye gücünün yetmediğini yüklemez.” Bu metin aynı fikri anlatır.</div><div class=\"sv-w\"><b>Tuzak:</b> B ve C genel doğrular; soru “bu metinden” ulaşılanı istiyor.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 3. soru"
 },
 "mebi-din-y02-4": {
  "t": "din-kader",
  "a": "C",
  "o": 100024,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. İnsan bazı davranışlarını kendi seçimiyle belirleyebilir.</li><li>II. Allah’ın iradesi sınırsızdır; insan iradesinden farklıdır.</li><li>III. Soy bağı cüzi iradeyle belirlenebilen tercihlerdendir.</li><li>IV. Davranışların anlam kazanması bilinçli seçime dayanır.</li><li>V. İnsanın gücü ve imkânı sorumluluğun sınırını etkiler.</li></ul><b>İstenen</b><p>Doğru ifadeler.</p></div><ol class=\"sv-s\"><li><b>İrade türlerini hatırla</b> <b>Külli irade</b> Allah’ın sınırsız iradesidir. <b>Cüzi irade</b> insanın sınırlı seçme gücüdür.</li><li><b>III’ü kontrol et</b> Soy bağı (anne-baba, aile) insanın seçimi değildir; iradesi dışında belirlenir. Bu yüzden III yanlış.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>İnsan seçme gücüne sahiptir → doğru.</td></tr><tr><td>II</td><td>Allah’ın iradesi sınırsız → doğru.</td></tr><tr><td>III</td><td>Soy bağı seçilemez → yanlış.</td></tr><tr><td>IV</td><td>Bilinçli seçim davranışa anlam katar → doğru.</td></tr><tr><td>V</td><td>Güç ve imkân sorumluluğu sınırlar → doğru.</td></tr><tr class=\"ok\"><td>C</td><td>I, II, IV ve V.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> İnsanın seçemedikleri (doğum yeri, aile, ten rengi) cüzi iradenin konusu değildir.</div><div class=\"sv-w\"><b>Tuzak:</b> III’te “cüzi irade” teriminin geçmesi ifadeyi doğru gibi gösterir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 4. soru"
 },
 "mebi-din-y02-5": {
  "t": "din-kader",
  "a": "B",
  "o": 100025,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Eylemlerin sonuçları ahlaki ve dinî açıdan hesap verilebilir.</li><li>II. Yapılması gerekirken ihmal edilen davranışlar da sorumluluğa girer.</li><li>III. “Kaderimde varmış.” düşüncesi sorumluluğu hafifletir.</li></ul><b>İstenen</b><p>Doğru ifadeler.</p></div><ol class=\"sv-s\"><li><b>I ve II</b> İnsan yaptığından da, yapması gerekirken yapmadığından (ihmal) da sorumludur. İkisi de doğru.</li><li><b>III</b> İslam’a göre kader sorumluluktan kaçmanın bahanesi olamaz; bu düşünce sorumluluğu hafifletmez. III yanlış.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>Hesap verebilirlik → doğru.</td></tr><tr><td>II</td><td>İhmal de sorumluluktur → doğru.</td></tr><tr><td>III</td><td>Kader bahane edilemez → yanlış.</td></tr><tr class=\"ok\"><td>B</td><td>I ve II.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Sorumluluk iki yönlüdür: yapılan yanlış + yapılmayan görev.</div><div class=\"sv-w\"><b>Tuzak:</b> III’ün tırnak içindeki söz günlük hayatta çok duyulduğu için doğru sanılabilir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 5. soru"
 },
 "mebi-din-y02-6": {
  "t": "din-kader",
  "a": "D",
  "o": 100026,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“… Ona iki yolu (doğru ve eğriyi) göstermedik mi?” (Beled, 10)</li></ul><b>İstenen</b><p>Ayetten ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Ayetin vurgusu</b> Allah insana iki yolu göstermiştir; bu, insanın aralarından <b>seçebilecek bir iradeye</b> sahip olduğunu anlatır.</li><li><b>Fazla yorumu ele</b> Ödül (A) ve bilginin rolü (B) ayette geçmez. C genel olarak doğrudur ama ayet seçilecek yolların gösterildiğini, yani seçme imkânını vurgular.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ödül ayette geçmez.</td></tr><tr><td>B</td><td>Bilgi ile tercih ilişkisi ayette yok.</td></tr><tr><td>C</td><td>Gerçekleşme değil, seçme imkânı vurgulanıyor; ayetin doğrudan mesajı değil.</td></tr><tr class=\"ok\"><td>D</td><td>İki yol gösterilmesi doğruyu seçecek iradenin varlığını gösterir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “İki yol gösterdik” = insan seçme özgürlüğüne sahip.</div><div class=\"sv-w\"><b>Tuzak:</b> C ile D birbirine çok yakındır; ayette doğruyu seçme imkânına vurgu olduğu için D daha doğrudan.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 6. soru"
 },
 "mebi-din-y02-7": {
  "t": "din-kader",
  "a": "C",
  "o": 100027,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsan iradesiyle yaptığı seçimlerden sorumludur; kaderi gerekçe gösterip sorumluluktan kaçması doğru değildir.</li><li>Kişi kontrol edebildiği alanlarda çaba göstermeli ve seçimlerinin sonuçlarını üstlenmelidir.</li></ul><b>İstenen</b><p>Metne göre doğru olan.</p></div><ol class=\"sv-s\"><li><b>Ana fikri yaz</b> İnsan kendi davranışlarının sorumluluğunu kabul etmeli.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Metin sonuçları kişinin seçimine bağlar; dış etkenlere değil.</td></tr><tr><td>B</td><td>Metin sorumluluğu kontrol edilebilen alanla sınırlar.</td></tr><tr class=\"ok\"><td>C</td><td>Davranışların sorumluluğunu üstlenmek gerekir → metnin ana fikri.</td></tr><tr><td>D</td><td>Metin çaba göstermeyi istiyor; çabanın etkisiz olduğunu söylemiyor.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kader inancı sorumluluğu ortadan kaldırmaz, güçlendirir.</div><div class=\"sv-w\"><b>Tuzak:</b> B’deki “sorumluluk dışı durum” ifadesi metindeki “kontrol edebildiği alan” ile tersine çevrilmiştir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 7. soru"
 },
 "mebi-din-y02-8": {
  "t": "din-kader",
  "a": "A",
  "o": 100028,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Kim doğru yolu seçerse kendi iyiliği için seçmiştir, kim de saparsa kendi zararına sapmış olur. Hiç kimse başkasının günah yükünü üstüne almaz…” (İsra, 15)</li></ul><b>İstenen</b><p>Ayetin mesajını veren eşleştirme.</p></div><ol class=\"sv-s\"><li><b>Ayetin anahtar ifadeleri</b> “Kendi iyiliği / kendi zararı”, “kimse başkasının yükünü taşımaz” → herkes kendi seçiminden sorumludur: <b>kişisel sorumluluk</b>.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Kendi hatasının sonucunu kabullenmek - kişisel sorumluluk → ayetin mesajı.</td></tr><tr><td>B</td><td>Tevekkül ayette geçmez.</td></tr><tr><td>C</td><td>Kaza tanımı doğru ama ayetin konusu değil.</td></tr><tr><td>D</td><td>Kader tanımı doğru ama ayetin konusu değil.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kimse başkasının günahını yüklenmez” = sorumluluk kişiseldir.</div><div class=\"sv-w\"><b>Tuzak:</b> C ve D kendi içinde doğru eşleştirmelerdir; soru ayetin mesajını soruyor.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 8. soru"
 },
 "mebi-din-y02-9": {
  "t": "din-kader",
  "a": "D",
  "o": 100029,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsan düşünme yeteneği ve seçim yapabilme imkânıyla yaptıklarını anlamlandırabilir.</li><li>Bu durum davranışlarının değerlendirilmesini mümkün kılar.</li></ul><b>İstenen</b><p>İnsanın davranışlarından sorumlu tutulmasının <b>asıl</b> nedeni.</p></div><ol class=\"sv-s\"><li><b>Metindeki gerekçe</b> Düşünme (akıl) + seçim yapabilme (irade) → bilinçli karar ve sonucunu üstlenme. Sorumluluğun temeli budur.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğuştan özellikler sorumluluğun nedeni değildir.</td></tr><tr><td>B</td><td>Çevre etkili olsa da sorumluluğu doğuran şey değildir.</td></tr><tr><td>C</td><td>Gelişme doğru ama sorumluluğun asıl nedeni değil.</td></tr><tr class=\"ok\"><td>D</td><td>Bilinçli karar verebilme ve sonucunu üstlenme → akıl ve irade.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Sorumluluğun iki şartı: akıl ve irade.</div><div class=\"sv-w\"><b>Tuzak:</b> C olumlu bir özelliktir ama metinde sorumluluğun nedeni olarak verilmez.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 9. soru"
 },
 "mebi-din-y02-10": {
  "t": "din-kader",
  "a": "B",
  "o": 100030,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Seçim yapabilme gücü kişiyi sorumlu kılar.</li><li>II. Kişinin kendi seçmediği özellikleri yükümlülük alanı dışındadır.</li><li>III. İlahi bilginin varlığı insanın tercihini zorunlu hâle getirir.</li></ul><b>İstenen</b><p>Doğru ifadeler.</p></div><ol class=\"sv-s\"><li><b>III’ü sına</b> Allah’ın her şeyi bilmesi insanı zorlamaz; bilmek, yaptırmak değildir. İnsan özgür iradesiyle seçer. III yanlış.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>İrade sorumluluk doğurur → doğru.</td></tr><tr><td>II</td><td>Seçilmeyen özelliklerden sorumluluk yok → doğru.</td></tr><tr><td>III</td><td>Allah’ın bilmesi tercihi zorunlu kılmaz → yanlış.</td></tr><tr class=\"ok\"><td>B</td><td>I ve II.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Allah’ın ilmi kapsayıcıdır ama zorlayıcı değildir.</div><div class=\"sv-w\"><b>Tuzak:</b> “İlahi bilgi” ifadesi kulağa dinî bir doğru gibi gelir; zorunluluk kısmı yanlıştır.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 10. soru"
 },
 "mebi-din-y02-11": {
  "t": "din-kader",
  "a": "B",
  "o": 100031,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsan tutum ve davranışlarının bir karşılığı olduğunu bilmeli ve kendini hesaba çekmelidir.</li></ul><b>İstenen</b><p>Bu düşünceyle aynı doğrultudaki ayet.</p></div><ol class=\"sv-s\"><li><b>Cümlenin anahtarı</b> “Karşılığı olduğunu bilmek, hesaba çekmek” → yapılanlardan sorgulanacak olmak.</li><li><b>Ayetleri tara</b> Nahl 93: “Yapmakta olduğunuz şeylerden mutlaka sorguya çekileceksiniz.” Doğrudan hesap verme bilincini anlatır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Güçlükle kolaylık → sabır ve ümit.</td></tr><tr class=\"ok\"><td>B</td><td>Yapılanlardan sorguya çekilmek → hesap bilinci.</td></tr><tr><td>C</td><td>Güç yetecek kadar yükümlülük → sorumluluğun sınırı.</td></tr><tr><td>D</td><td>Kulluk için yaratılma → yaratılış amacı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Hesap, sorgu” sözcükleri aynı düşüncenin işaretidir.</div><div class=\"sv-w\"><b>Tuzak:</b> C de sorumlulukla ilgilidir ama sorumluluğun sınırını anlatır, hesabı değil.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 11. soru"
 },
 "mebi-din-y02-12": {
  "t": "din-kader",
  "a": "C",
  "o": 100032,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ayşe’nin işaretlemesi: I Doğru, II Doğru, III Yanlış, IV Yanlış, V Yanlış.</li></ul><b>İstenen</b><p>Ayşe’nin yanlış verdiği cevaplar.</p></div><ol class=\"sv-s\"><li><b>Her ifadenin gerçek durumu</b> I doğru (akıl + irade → sorumluluk). II yanlış (külli irade Allah’ın iradesidir; insanın sınırlı karar alanı <b>cüzi irade</b>dir). III doğru (kader bahane edilemez). IV doğru (sorumluluk iradeyi aşmayan alanla sınırlı). V yanlış (uykuda solunum iradeyle olmaz).</li><li><b>Ayşe ile karşılaştır</b> I: D–D ✓. II: Ayşe D, gerçek Y ✗. III: Ayşe Y, gerçek D ✗. IV: Ayşe Y, gerçek D ✗. V: Y–Y ✓.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>I’i doğru işaretlemiş.</td></tr><tr><td>B</td><td>I’i doğru işaretlemiş.</td></tr><tr class=\"ok\"><td>C</td><td>II, III ve IV yanlış işaretlenmiş.</td></tr><tr><td>D</td><td>I’i doğru işaretlemiş.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Külli irade = Allah; cüzi irade = insan. Bu ikisini karıştırma.</div><div class=\"sv-w\"><b>Tuzak:</b> Soru ifadelerin değil, <b>Ayşe’nin cevaplarının</b> yanlış olanlarını soruyor.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 12. soru"
 },
 "mebi-din-y02-13": {
  "t": "din-kader",
  "a": "D",
  "o": 100033,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Allah bir kimseyi ancak gücünün yettiği şeyle yükümlü kılar. Onun kazandığı iyilik kendi yararına, kötülük de kendi zararınadır…” (Bakara, 286)</li></ul><b>İstenen</b><p>Ayetin mesajı.</p></div><ol class=\"sv-s\"><li><b>Ayetin ilk cümlesi</b> Yükümlülük insanın gücüne göredir; yani sorumluluk kapasiteyle orantılıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ayet zorluğu değil gücü ölçü alır; zorluk yükümlülüğü kaldırmaz.</td></tr><tr><td>B</td><td>Akılla doğruyu ayırt etme ayette geçmez.</td></tr><tr><td>C</td><td>İkinci cümleden çıkar ama ayetin ana mesajı sorumluluğun sınırıdır.</td></tr><tr class=\"ok\"><td>D</td><td>Sorumluluk kişinin kapasitesine göre belirlenir → ayetin mesajı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Bakara 286 = “güç yetirilemeyen yük yüklenmez” ayetidir.</div><div class=\"sv-w\"><b>Tuzak:</b> C de ayetle ilişkilidir; ama ayetin özellikle vurguladığı “gücünün yettiği şey” ifadesidir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 2 · 13. soru"
 },
 "mebi-din-y03-1": {
  "t": "din-kader",
  "a": "B",
  "o": 100034,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>100 öğrencilik anket: “Tevekkül, tedbir aldıktan sonra Allah’a güvenmektir.” %35; “Gerekli tedbir alınmazsa sonuç insanın sorumluluğundadır.” %25; “Sağlık ve hastalık hem kader hem de insanın çabasına bağlıdır.” %20; “Başarı ve başarısızlık tamamen kaderdir.” %10; “İş kazaları alın yazısıdır, değiştirilemez.” %10.</li></ul><b>İstenen</b><p>Verilere göre ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Doğru ve yanlış anlayışları ayır</b> İlk üç görüş doğru kader anlayışıdır (%35 + %25 + %20 = %80). Son ikisi kaderi insan iradesini yok sayan yanlış anlayıştır (%10 + %10 = %20).</li><li><b>Şıkları yüzdelerle sına</b> Sorumluluk (%25) ve tevekkül (%35) görüşlerini seçenler %60’tır; bu “büyük bir kısım” demektir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Sağlık–hastalık görüşü %20; “çoğu” değil, ayrıca görüş “yalnızca bireysel çaba” demiyor.</td></tr><tr class=\"ok\"><td>B</td><td>Tevekkül %35 + sorumluluk %25 = %60 → büyük kısmı doğru anlamış.</td></tr><tr><td>C</td><td>İradeyi dışlayan görüşler toplam %20; yarıdan fazla değil.</td></tr><tr><td>D</td><td>İş kazası görüşü yalnızca %10.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Grafik sorularında şıktaki “çoğu, yarıdan fazlası” gibi sözcükleri toplam yüzdeyle karşılaştır.</div><div class=\"sv-w\"><b>Tuzak:</b> En uzun çubuk tevekkülde diye yalnız ona bakma; B iki görüşü birlikte soruyor.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 1. soru"
 },
 "mebi-din-y03-2": {
  "t": "din-kader",
  "a": "D",
  "o": 100035,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Zeynep ne zaman öleceğini bilmediği için her gününü faydalı işlerle değerlendiriyor.</li><li>II. Mehmet ailesinin imkânlarını hem çalışmalarının karşılığı hem Allah’ın nimeti olarak görüp şükrediyor.</li><li>III. Yusuf düzenli beslenip spor yapıyor, rahatsızlanınca tedavi oluyor.</li></ul><b>İstenen</b><p>Davranışlarda yer verilmeyen kavram çifti.</p></div><ol class=\"sv-s\"><li><b>Her davranışı eşleştir</b> I → ömür-ecel (hayatın süresi ve sonu). II → emek-rızık (çalışma ve nimet). III → sağlık-hastalık (beslenme, spor, tedavi).</li><li><b>Dışarıda kalan</b> Sınav, hedef, başarıdan söz eden bir davranış yok.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Zeynep’in davranışında var.</td></tr><tr><td>B</td><td>Mehmet’in davranışında var.</td></tr><tr><td>C</td><td>Yusuf’un davranışında var.</td></tr><tr class=\"ok\"><td>D</td><td>Başarı-başarısızlık hiçbir davranışta yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kaderle ilgili kavram çiftleri: ömür-ecel, emek-rızık, sağlık-hastalık, başarı-başarısızlık.</div><div class=\"sv-w\"><b>Tuzak:</b> Yusuf’un çabası “başarı” sanılabilir; ama konusu sağlıktır.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 2. soru"
 },
 "mebi-din-y03-3": {
  "t": "din-kader",
  "a": "C",
  "o": 100036,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hasta olan kişi doktora gidip tedavi olur; şifanın Allah’tan olduğunu bilip tevekkül eder. Hz. Peygamber de hem dua etmiş hem tedavi olmuştur.</li><li>I. Allah’a dayanıp güven (Furkan 58). II. Bakmakla yükümlü olduğu kimseleri ihmal günahtır (hadis). III. Tedavi olunuz, Allah her hastalığın şifasını yaratmıştır (hadis). IV. Hastalandığımda bana şifa veren O’dur (Şuara 80).</li></ul><b>İstenen</b><p>Bilgilerle ilişkilendirilebilen ayet ve hadisler.</p></div><ol class=\"sv-s\"><li><b>Metindeki fikirler</b> Tedbir/tedavi, tevekkül, şifanın Allah’tan olduğu.</li><li><b>Eşleştir</b> I tevekkül ✓. III tedavi ✓. IV şifa veren Allah ✓. II ise aile fertlerini ihmal etmekle ilgilidir; metinde böyle bir konu yok.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>Allah’a güvenmek → tevekkül, ilişkili.</td></tr><tr><td>II</td><td>Bakmakla yükümlü olunanları ihmal → metinle ilgisiz.</td></tr><tr><td>III</td><td>Tedavi olmak → ilişkili.</td></tr><tr><td>IV</td><td>Şifayı Allah verir → ilişkili.</td></tr><tr class=\"ok\"><td>C</td><td>I, III ve IV.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Hastalıkta doğru tutum: tedavi (tedbir) + dua + tevekkül.</div><div class=\"sv-w\"><b>Tuzak:</b> II de sorumlulukla ilgili bir hadistir; ama metnin konusu hastalık ve tedavidir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 3. soru"
 },
 "mebi-din-y03-4": {
  "t": "din-kader",
  "a": "C",
  "o": 100037,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Her insanın bir yaşam süresi vardır ve bir gün sona erecektir.</li><li>Çalışmak, helal kazanç peşinde olmak insanın sorumluluğudur; nimetler gayretle kazanılır.</li><li>Kişi elinden geleni yapmalı, sonucu Allah’a bırakmalıdır; seçimleri yok sayılmaz.</li></ul><b>İstenen</b><p>Metinde yer verilmeyen kavram çifti.</p></div><ol class=\"sv-s\"><li><b>Metni kavramlarla eşle</b> Yaşam süresi ve sonu → ömür-ecel. Çalışma, helal kazanç, nimet → emek-rızık. Seçimler ve sonucu Allah’a bırakmak → irade-tevekkül.</li><li><b>Dışarıda kalan</b> Metinde hastalık, tedavi, sağlıklı yaşam yok.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>“Yaşam süresi… sonu olacak” → var.</td></tr><tr><td>B</td><td>“Helal kazanç, gayretle kazanılan nimet” → var.</td></tr><tr class=\"ok\"><td>C</td><td>Sağlık-hastalıktan söz edilmiyor.</td></tr><tr><td>D</td><td>“Seçimler… sonucu Allah’a bırakmalı” → var.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Metinde geçen her kavramın ipucu cümlesini bul; ipucu olmayan çift cevaptır.</div><div class=\"sv-w\"><b>Tuzak:</b> “Nimet” sözcüğü sağlığı çağrıştırabilir; ama metinde kazançla birlikte geçiyor → rızık.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 4. soru"
 },
 "mebi-din-y03-5": {
  "t": "din-kader",
  "a": "B",
  "o": 100038,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ahmet’in dükkânı dürüstlüğü ve kaliteli ürünleri sayesinde iyi iş yapıyordu.</li><li>Daha çok kazanmak için pahalı satıp eksik bilgi vermeye başladı; müşteriler azaldı, dükkân zarar etti.</li><li>Ahmet hatalarını düşünmek yerine “Kısmetim buymuş.” dedi.</li></ul><b>İstenen</b><p>Ahmet’le ilgili söylenebilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Sebep–sonuç</b> Zararın sebebi Ahmet’in kendi yanlış tutumudur. Ahmet bunu görmezden gelip sonucu “kısmet” diyerek kadere bağlıyor.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Hatasını düşünmüyor; farkına vardığı söylenemez.</td></tr><tr class=\"ok\"><td>B</td><td>Kendi yaptığının sonucunu kadere yüklemiş → doğru.</td></tr><tr><td>C</td><td>Dürüstlüğün önemini anladığına dair bilgi yok.</td></tr><tr><td>D</td><td>Tutumunu sorgulamadığı açıkça söyleniyor.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kısmetim buymuş, kaderim böyleymiş” = sorumluluğu kadere yükleme.</div><div class=\"sv-w\"><b>Tuzak:</b> A, C ve D Ahmet’in yapması gerekenlerdir; yaptıkları değildir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 5. soru"
 },
 "mebi-din-y03-6": {
  "t": "din-kader",
  "a": "A",
  "o": 100039,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tablo: I. Ölçü ve düzen – Tevekkül; II. Allah’a dayanmak – Kader; III. Canlılara verilen sınırlı zaman – Ömür; IV. Canlılara verilen her türlü nimet – Rızık.</li></ul><b>İstenen</b><p>Hangi ifadeler yer değiştirirse eşleştirme doğru olur?</p></div><ol class=\"sv-s\"><li><b>Doğru eşleşmeleri bul</b> Ölçü ve düzen → kader. Allah’a dayanmak → tevekkül. Sınırlı zaman → ömür ✓. Her türlü nimet → rızık ✓.</li><li><b>Yer değiştir</b> I ile II’nin ifadeleri yer değiştirirse “ölçü ve düzen – kader”, “Allah’a dayanmak – tevekkül” olur.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>I ve II yer değiştirince tüm eşleştirmeler doğru olur.</td></tr><tr><td>B</td><td>IV zaten doğru; yer değiştirmesi bozar.</td></tr><tr><td>C</td><td>III zaten doğru.</td></tr><tr><td>D</td><td>III ve IV zaten doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kader = ölçü, plan, düzen; tevekkül = tedbirden sonra Allah’a güvenmek.</div><div class=\"sv-w\"><b>Tuzak:</b> Hangi ikisinin yanlış olduğunu bulmak yetmez; ikisinin birbirinin yerine geçtiğini kontrol et.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 6. soru"
 },
 "mebi-din-y03-7": {
  "t": "din-kader",
  "a": "B",
  "o": 100040,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Trafiğe çıkmadan emniyet kemerini takmak. II. “Başa gelen çekilir” diyerek tedaviyi ihmal etmek. III. “Daha çok zaman var” diyerek sorumlulukları ertelemek. IV. Başarı için sınava planlı çalışmak.</li></ul><b>İstenen</b><p>Kader inancına sahip bir kişiden beklenen davranışlar.</p></div><ol class=\"sv-s\"><li><b>Doğru kader anlayışı</b> Tedbir al, çalış, sonra tevekkül et. Kaderi bahane edip tedbiri bırakmak ya da ertelemek yanlıştır.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>Tedbir almak → beklenir.</td></tr><tr><td>II</td><td>Tedaviyi ihmal → yanlış kader anlayışı.</td></tr><tr><td>III</td><td>Ertelemek → ecelin ne zaman geleceğini bilmeyen kişiye yakışmaz.</td></tr><tr><td>IV</td><td>Çalışmak → beklenir.</td></tr><tr class=\"ok\"><td>B</td><td>I ve IV.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tedbir + çaba + tevekkül üçlüsü doğru kader anlayışıdır.</div><div class=\"sv-w\"><b>Tuzak:</b> III kaderle ilgisiz gibi görünür; ama ömrün sınırlı olduğunu bilen kişi işini ertelemez.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 7. soru"
 },
 "mebi-din-y03-8": {
  "t": "din-kader",
  "a": "A",
  "o": 100041,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Her canlı ölümü tadacak ve sonunda dönüp huzurumuza geleceksiniz.” (Ankebut, 57)</li></ul><b>İstenen</b><p>Ayette değinilen kavram.</p></div><ol class=\"sv-s\"><li><b>Kavramları ayır</b> <b>Ecel:</b> hayatın sona ereceği an, ölüm vakti. <b>Ömür:</b> doğumdan ölüme yaşam süresi. Ayet “ölümü tatmaktan”, yani hayatın sona ermesinden söz ediyor.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Ölümü tatmak → ecel.</td></tr><tr><td>B</td><td>Ömür yaşam süresidir; ayet sürenin değil ölümün kendisini anlatıyor.</td></tr><tr><td>C</td><td>Rızık nimetlerdir.</td></tr><tr><td>D</td><td>Tevekkül Allah’a güvenmektir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ölüm, hayatın sonu → ecel.</div><div class=\"sv-w\"><b>Tuzak:</b> Ömür ile ecel aynı kavram değildir; ömür süre, ecel o sürenin bittiği andır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 8. soru"
 },
 "mebi-din-y03-9": {
  "t": "din-kader",
  "a": "D",
  "o": 100042,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Hata yaptım, kaderim böyleymiş.” “İnsan ne yaparsa yapsın sonucu değiştiremez.” “Bu kadar aksilik ancak kara talihle açıklanır.” “Kısmetimde yokmuş, emek vermeye gerek kalmadı.”</li></ul><b>İstenen</b><p>Bu ifadeler için en uygun başlık.</p></div><ol class=\"sv-s\"><li><b>Ortak noktayı bul</b> Dört ifade de iradeyi ve çabayı yok sayıp her şeyi kadere, talihe bağlıyor. Bunlar kaderle ilgili <b>yanlış</b> anlayışlardır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Başlık çok genel; ifadelerin yanlışlığını yansıtmaz.</td></tr><tr><td>B</td><td>İfadeler iradenin önemini değil, yok sayılmasını anlatıyor.</td></tr><tr><td>C</td><td>İfadelerde sorumluluk bilinci değil, sorumluluktan kaçış var.</td></tr><tr class=\"ok\"><td>D</td><td>Kaderle ilgili yanlış anlayışlar → tam uygun başlık.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kaderim böyleymiş, talihsizlik, kısmet” → yanlış kader anlayışı.</div><div class=\"sv-w\"><b>Tuzak:</b> C’deki “sorumluluk” sözcüğü konuyla bağlantılı göründüğü için seçilebilir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 9. soru"
 },
 "mebi-din-y03-10": {
  "t": "din-kader",
  "a": "B",
  "o": 100043,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam insanın çalışarak ve helal yoldan kazanarak geçimini sağlamasını ister.</li></ul><b>İstenen</b><p>Bu bilgiyle ilgili ayet veya hadis.</p></div><ol class=\"sv-s\"><li><b>Anahtar fikir</b> Emek vererek kazanmak (emek-rızık).</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Kolaylaştırma ve müjdeleme → dinin kolaylık ilkesi.</td></tr><tr class=\"ok\"><td>B</td><td>“Kimse elinin emeğinden daha hayırlı bir yemek yememiştir” → çalışarak kazanmak.</td></tr><tr><td>C</td><td>Doğru yolu seçmek → sorumluluk.</td></tr><tr><td>D</td><td>Rızkı bol veren ve kısan Allah’tır → rızkın Allah’tan olduğu; emek vurgusu yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “El emeği” ifadesi helal kazancın sembolüdür.</div><div class=\"sv-w\"><b>Tuzak:</b> D’de “rızık” sözcüğü geçtiği için seçilebilir; ama bilgi çalışmayı vurguluyor.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 10. soru"
 },
 "mebi-din-y03-11": {
  "t": "din-kader",
  "a": "D",
  "o": 100044,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tanım: Yarattığı bütün varlıklara maddi ve manevi her türlü rızkı bolca veren.</li></ul><b>İstenen</b><p>Tanımı verilen esmaülhüsna.</p></div><ol class=\"sv-s\"><li><b>İsimleri hatırla</b> Azîm: en büyük. Basîr: her şeyi gören. Kayyûm: her şeyi ayakta tutan. <b>Rezzâk: rızık veren.</b></li></ol><table class=\"sv-c\"><tr><td>A</td><td>Azîm büyüklük anlatır.</td></tr><tr><td>B</td><td>Basîr görmeyi anlatır.</td></tr><tr><td>C</td><td>Kayyûm varlıkları ayakta tutmayı anlatır.</td></tr><tr class=\"ok\"><td>D</td><td>Rezzâk rızık verendir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Rızık → Rezzâk; aynı kökten gelir.</div><div class=\"sv-w\"><b>Tuzak:</b> Kayyûm da Ayetelkürsi’de geçtiği için tanıdık gelir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 11. soru"
 },
 "mebi-din-y03-12": {
  "t": "din-kader",
  "a": "C",
  "o": 100045,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Öğretmen düzenli tekrar ve bol soru çözmeyi önermişti; Hasan ders çalışmak yerine telefonla vakit geçirdi.</li><li>Hasan sınavda konuları hatırlayamadı ve tercihinin yanlış olduğunu anladı.</li></ul><b>İstenen</b><p>Hasan’ın başarısız olmasının nedeni.</p></div><ol class=\"sv-s\"><li><b>Metindeki neden</b> Başarısızlık Hasan’ın kendi tercihinin sonucudur: sorumluluğunu yerine getirmek yerine zamanını başka işlere harcadı.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Sınavın zorluğundan söz edilmiyor.</td></tr><tr><td>B</td><td>Arkadaşların zekâsı metinde yok.</td></tr><tr class=\"ok\"><td>C</td><td>Sorumluluk yerine zamanı başka şeylere harcaması → metindeki neden.</td></tr><tr><td>D</td><td>Öğretmen açıklama yapmış.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Metinde “tercih etti” ifadesi sebebin kişinin kendisi olduğunu gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve D sorumluluğu dışarıya atan bahanelerdir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 12. soru"
 },
 "mebi-din-y03-13": {
  "t": "din-kader",
  "a": "B",
  "o": 100046,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Gökleri, yeri ve ikisi arasındakileri şüphesiz yerli yerince ve <b>belli bir süre için</b> yarattık…” (Ahkaf, 3)</li></ul><b>İstenen</b><p>Hümeyra’nın düşüncesini tamamlayan cümle.</p></div><ol class=\"sv-s\"><li><b>Ayetin kilit ifadesi</b> “Belli bir süre için” → yaratılan her şeyin bir sonu, yani bir eceli vardır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İmtihan fikri ayette yok.</td></tr><tr class=\"ok\"><td>B</td><td>Her şeyin Allah’ın takdir ettiği bir eceli var → ayetle uyumlu.</td></tr><tr><td>C</td><td>Evrendeki düzen insanların çabasına bağlı değildir.</td></tr><tr><td>D</td><td>Hesap fikri ayette yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Belli bir süre” = ecel; yalnız insanın değil, evrenin de eceli vardır.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve D dinî açıdan doğrudur ama ayetin akışından çıkmaz.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 13. soru"
 },
 "mebi-din-y03-14": {
  "t": "din-kader",
  "a": "C",
  "o": 100047,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsanın yaşam süresi sınırlıdır ve bir gün sona erecektir.</li><li>İnsan zamanını bilinçli değerlendirmeli, sorumluluklarını yerine getirip sonucu Allah’a bırakmalıdır.</li></ul><b>İstenen</b><p>Metinde değinilmeyen kavram.</p></div><ol class=\"sv-s\"><li><b>Kavramları eşleştir</b> Yaşam süresi → ömür. Sona ermesi → ecel. Sonucu Allah’a bırakmak → tevekkül.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>“Bir gün sona erecek” → ecel var.</td></tr><tr><td>B</td><td>“Yaşam süresi” → ömür var.</td></tr><tr class=\"ok\"><td>C</td><td>Sağlıktan söz edilmiyor.</td></tr><tr><td>D</td><td>“Sonucu Allah’a bırakmak” → tevekkül var.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tevekkül = tedbir/sorumluluk + sonucu Allah’a bırakmak.</div><div class=\"sv-w\"><b>Tuzak:</b> Ömür ve ecelin ikisi de metinde ayrı cümlelerle anlatılıyor; ikisini de ele.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 14. soru"
 },
 "mebi-din-y03-15": {
  "t": "din-kader",
  "a": "D",
  "o": 100048,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Bazı insanlar olumsuzlukları şanssızlığa bağlayıp sorumluluktan kaçar; önlem alınmadan olan kazaları kaderle ilişkilendirmek doğru değildir.</li><li>İnsan tedbir almakla yükümlüdür; kader inancı sorumluluk bilincini güçlendirmelidir.</li></ul><b>İstenen</b><p>Metne göre doğru tutum.</p></div><ol class=\"sv-s\"><li><b>Doğru tutum</b> Önce tedbir, sonra tevekkül.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Alın yazısı demek metnin eleştirdiği tutumdur.</td></tr><tr><td>B</td><td>İhmali rastlantıya bağlamak metnin eleştirdiğidir.</td></tr><tr><td>C</td><td>Hatayı kabul edip yine kadere yüklemek çelişkilidir ve yanlıştır.</td></tr><tr class=\"ok\"><td>D</td><td>Gerekli tedbiri alıp sonucu Allah’a bırakmak → tevekkül.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tevekkül tembellik değildir; tedbirden sonra gelir.</div><div class=\"sv-w\"><b>Tuzak:</b> C’nin başındaki “hataları kabul edip” ifadesi olumlu görünür; devamı kadere yüklemedir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 15. soru"
 },
 "mebi-din-y03-16": {
  "t": "din-kader",
  "a": "A",
  "o": 100049,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Bulmacadaki kavramlar: 1 → RIZIK, 2 → ECEL, 3 → SAĞLIK.</li></ul><b>İstenen</b><p>Bulmacadaki kavramlardan birine ait <b>olmayan</b> tanım.</p></div><ol class=\"sv-s\"><li><b>Tanımları eşleştir</b> Allah’ın verdiği nimetlerin tamamı → rızık. Vakti gelince hayatın sona ermesi → ecel. Fiziksel ve psikolojik iyi olma → sağlık.</li><li><b>Dışarıda kalan</b> “İnsanın dünyadaki yaşam süreci” <b>ömür</b>dür; ömür bulmacada yok.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Ömrün tanımı → bulmacada yok.</td></tr><tr><td>B</td><td>Rızık → bulmacada var.</td></tr><tr><td>C</td><td>Ecel → bulmacada var.</td></tr><tr><td>D</td><td>Sağlık → bulmacada var.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ömür = yaşam süresi; ecel = o sürenin bittiği an.</div><div class=\"sv-w\"><b>Tuzak:</b> Ömür ile eceli karıştırırsan A’yı ecelin tanımı sanabilirsin.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 3 · 16. soru"
 },
 "mebi-din-y04-1": {
  "t": "din-kader",
  "a": "A",
  "o": 100050,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa’nın soyunun dayandığı peygamber soruluyor.</li></ul><b>İstenen</b><p>Hz. Musa’nın soyunun dayandığı peygamber.</p></div><ol class=\"sv-s\"><li><b>Soy zincirini hatırla</b> Hz. Musa İsrailoğullarındandır. İsrail, Hz. Yakup’un lakabıdır; Hz. Yakup Hz. İshak’ın, Hz. İshak da Hz. İbrahim’in oğludur. Ders kitabı bu soyu Hz. İbrahim’e dayandırır.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Hz. İbrahim → Hz. Musa’nın soyu ona dayanır.</td></tr><tr><td>B</td><td>Hz. İshak zincirde var ama soyun dayandığı ata olarak Hz. İbrahim verilir.</td></tr><tr><td>C</td><td>Hz. Nuh çok daha eski bir peygamberdir; soru bu değil.</td></tr><tr><td>D</td><td>Hz. Yusuf Hz. Yakup’un oğludur; Hz. Musa onun soyundan değildir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Hz. İbrahim, “peygamberler atası” olarak anılır; İsrailoğulları peygamberleri onun soyundandır.</div><div class=\"sv-w\"><b>Tuzak:</b> B de zincirde yer aldığı için seçilebilir; soru soyun dayandığı ilk büyük atayı soruyor.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 1. soru"
 },
 "mebi-din-y04-2": {
  "t": "din-kader",
  "a": "B",
  "o": 100051,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa’nın Firavun’un zulmünden kurtarıp rehberlik ettiği kavim soruluyor.</li></ul><b>İstenen</b><p>Bu kavim.</p></div><ol class=\"sv-s\"><li><b>Kıssayı hatırla</b> Firavun Mısır’da İsrailoğullarını köleleştirip erkek çocuklarını öldürtüyordu. Hz. Musa onları Mısır’dan çıkardı.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ad kavmine Hz. Hud gönderildi.</td></tr><tr class=\"ok\"><td>B</td><td>İsrailoğulları → Hz. Musa’nın kavmi.</td></tr><tr><td>C</td><td>Medyen halkına Hz. Şuayb gönderildi; Hz. Musa oraya yalnızca sığındı.</td></tr><tr><td>D</td><td>Semud kavmine Hz. Salih gönderildi.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Firavun + Mısır + İsrailoğulları = Hz. Musa kıssası.</div><div class=\"sv-w\"><b>Tuzak:</b> Hz. Musa Medyen’de yıllarca kaldığı için C çeldiricidir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 2. soru"
 },
 "mebi-din-y04-3": {
  "t": "din-kader",
  "a": "C",
  "o": 100052,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“İkiniz beraber Firavun’a gidin çünkü o sınırı çok aştı. Yine de ona söyleyeceklerinizi yumuşak bir üslupla söyleyin, ola ki aklını başına toplar…” (Taha, 43-44)</li></ul><b>İstenen</b><p>Tebliğ metoduyla ilgili <b>en kapsamlı</b> yargı.</p></div><ol class=\"sv-s\"><li><b>Ayetteki iki fikir</b> 1) Zalime bile yumuşak üslup. 2) Amaç: muhatabın aklını başına toplaması, yani mesajı kabul etmesi.</li><li><b>En geniş yargıyı seç</b> A (nezaket), B (üslup), D (yumuşak dil) ayrıntıdır. C “sergilenen tavır” diyerek bunların hepsini kapsar ve sonucu (kabul ihtimali) da içerir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğru ama yalnızca nezakete odaklanıyor.</td></tr><tr><td>B</td><td>Ayet üslubun önemini anlatır ama mesajla kıyas yapmaz.</td></tr><tr class=\"ok\"><td>C</td><td>Tavır mesajın kabul ihtimalini artırır → hem yöntemi hem amacı kapsar.</td></tr><tr><td>D</td><td>Ön yargıdan söz edilmez; daha dar bir yorum.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “En kapsamlı” = diğer şıkları içine alan yargı.</div><div class=\"sv-w\"><b>Tuzak:</b> A da doğru bir yargıdır; ama C’nin bir parçasıdır.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 3. soru"
 },
 "mebi-din-y04-4": {
  "t": "din-kader",
  "a": "D",
  "o": 100053,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Firavun erkek bebekleri öldürtürken Allah, Hz. Musa’nın annesine çocuğu emzirmesini, korktuğunda sandıkla nehre bırakmasını vahyetti.</li><li>Anne “Biz onu sana geri döndüreceğiz…” (Kasas, 7) vaadine güvenip çocuğunu Nil’e bıraktı.</li></ul><b>İstenen</b><p>Annenin tutumunu açıklayan kavram.</p></div><ol class=\"sv-s\"><li><b>Annenin yaptıkları</b> Önce çocuğunu korumak için elinden geleni yaptı (emzirdi, sandığa koydu), sonra sonucu Allah’a bıraktı ve O’nun vaadine güvendi.</li><li><b>Kavram</b> Tedbir + Allah’a güven = <b>tevekkül</b>.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Rızık konusu değil.</td></tr><tr><td>B</td><td>İbadetlerde ihlas konusu değil.</td></tr><tr><td>C</td><td>Cüzi irade kullanılmış ama tutumun özü Allah’a güvenmektir.</td></tr><tr class=\"ok\"><td>D</td><td>Çabayı harcayıp sonucu Allah’a bırakmak → tevekkül.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tevekkül, tedbiri bırakmak değil, tedbirden sonra Allah’a güvenmektir.</div><div class=\"sv-w\"><b>Tuzak:</b> C de doğru bir ilke gibi durur; ama metin “vaadine güvenerek” diyerek tevekküle vurgu yapıyor.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 4. soru"
 },
 "mebi-din-y04-5": {
  "t": "din-kader",
  "a": "D",
  "o": 100054,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Allah, Hz. Musa’nın annesine çocuğu nehre bırakmasını vahyetti; anne uydu, Hz. Musa saraya ulaştı ve sonunda annesine geri verildi; vaat gerçekleşti.</li></ul><b>İstenen</b><p>Metinden <b>ulaşılamayacak</b> yargı.</p></div><ol class=\"sv-s\"><li><b>Şıkları metinle karşılaştır</b> A: Annenin imanı ve itaati zorlukta güç verdi ✓. B: Emzirme ve sandık tedbirdi, tevekküle engel olmadı ✓. C: Vaat, nehre bırakmak gibi riskli bir yolla gerçekleşti ✓.</li><li><b>D’yi sına</b> Metin erkek bebeklere yönelik tehlikenin bittiğini söylemez; Hz. Musa’nın sarayda büyümesi Allah’ın onu koruduğunu gösterir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ulaşılır.</td></tr><tr><td>B</td><td>Ulaşılır.</td></tr><tr><td>C</td><td>Ulaşılır.</td></tr><tr class=\"ok\"><td>D</td><td>Metinde tehlikenin sona erdiğine dair bilgi yok → ulaşılamaz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ulaşılamaz sorularında metinde dayanağı olmayan genellemeyi ara.</div><div class=\"sv-w\"><b>Tuzak:</b> Hz. Musa’nın kurtulması tüm bebeklerin kurtulduğu anlamına gelmez.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 5. soru"
 },
 "mebi-din-y04-6": {
  "t": "din-kader",
  "a": "A",
  "o": 100055,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa Medyen suyunda tanımadığı iki kadının hayvanlarını, kendisi yorgun ve yabancı olmasına rağmen suladı.</li><li>Ardından “Rabbim! Doğrusu bana indireceğin her hayra muhtacım.” (Kasas, 24) diye dua etti; menfaat beklemediği hâlde iş ve aile sahibi oldu.</li></ul><b>İstenen</b><p>Hz. Musa’nın tutumu hakkında söylenebilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Sebep–sonuç</b> Karşılıksız iyilik yaptı → sonunda iş ve aile sahibi oldu. İyilik hayırlı sonuçlara vesile oldu.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Karşılık beklemeden yapılan iyilik hayırlı sonuç doğurdu → doğru.</td></tr><tr><td>B</td><td>Gelecek kaygısıyla yardım ettiği söylenmez.</td></tr><tr><td>C</td><td>Yardım ettiği kişiler yakını değil, tanımadığı kişilerdir.</td></tr><tr><td>D</td><td>Güven kazanmak için yardım ettiği söylenmez; metin karşılıksız iyiliği vurgular.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Metindeki “herhangi bir menfaat beklememesine rağmen” ifadesi cevabın anahtarıdır.</div><div class=\"sv-w\"><b>Tuzak:</b> D sonuç olarak doğru gibi görünse de metnin vurgusu karşılıksız iyiliğin sonucudur.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 6. soru"
 },
 "mebi-din-y04-7": {
  "t": "din-kader",
  "a": "C",
  "o": 100056,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa tebliğ görevinin ağırlığını hissedip yalanlanmaktan endişe ediyor.</li><li>Daha düzgün konuşan kardeşi Hz. Harun’un yardımcı verilmesini istiyor; Allah bu isteği kabul ediyor.</li></ul><b>İstenen</b><p>Metinde <b>asıl</b> anlatılmak istenen.</p></div><ol class=\"sv-s\"><li><b>Olayın özü</b> Büyük bir görev, kardeşle birlikte, yardımlaşarak yürütülecek. Allah’ın isteği kabul etmesi bu iş birliğini onaylar.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Bireysel yetkinlik ayrıntıdır.</td></tr><tr><td>B</td><td>Hitabet ayrıntıdır (Hz. Harun’un konuşması).</td></tr><tr class=\"ok\"><td>C</td><td>Dayanışma ve iş birliği büyük sorumluluklarda başarıya katkı sağlar → asıl fikir.</td></tr><tr><td>D</td><td>Endişenin giderilmesi bir sonuçtur; asıl vurgu birlikte çalışmaktır.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Hz. Musa–Hz. Harun = görevde yardımlaşma ve dayanışma örneği.</div><div class=\"sv-w\"><b>Tuzak:</b> D çok yakın bir çeldiricidir; ama metin desteğin kardeşle iş birliği olduğunu öne çıkarır.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 7. soru"
 },
 "mebi-din-y04-8": {
  "t": "din-kader",
  "a": "D",
  "o": 100057,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa kibrin ve zulmün merkezi olan sarayda büyüdü ama Firavun’un zihniyetinden etkilenmedi; adaleti ve hakikati savundu.</li><li>Firavun’un eşi de aynı sarayda merhametli kaldı ve Hz. Musa’yı korudu.</li></ul><b>İstenen</b><p>Metinden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>İki örneğin ortak noktası</b> İkisi de kötü bir çevrede yaşadı ama kendi seçimleriyle iyi kaldı. Ahlak ve inanç çevreye rağmen kişinin iradesiyle şekillenir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Metin fiziksel korunmadan değil, kişinin duruşundan söz ediyor.</td></tr><tr><td>B</td><td>Erdemi toplumsal konuma bağlamak metne ters; ikisi de çevrelerine rağmen erdemli.</td></tr><tr><td>C</td><td>Gelişimin çevreyle paralel olduğunu söylemek metne tam terstir.</td></tr><tr class=\"ok\"><td>D</td><td>Ahlaki kimlik çevre baskısına rağmen hür iradeyle şekillenir → doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kötü çevrede iyi kalan örnekler → irade ve sorumluluk vurgusu.</div><div class=\"sv-w\"><b>Tuzak:</b> C, “çevre insanı etkiler” şeklindeki genel kanıya dayanır; metin bunun tersini anlatıyor.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 8. soru"
 },
 "mebi-din-y04-9": {
  "t": "din-kader",
  "a": "B",
  "o": 100058,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Sihirbazlar halkın algısını etkileyen bir gösteri yaptı; Hz. Musa’nın asası onların uydurduklarını yuttu.</li><li>Sihirbazlar iman etti; Firavun ise tehditlerini artırdı.</li></ul><b>İstenen</b><p>Metinden <b>ulaşılamayacak</b> yargı.</p></div><ol class=\"sv-s\"><li><b>Tepkileri karşılaştır</b> Aynı olayı gören sihirbazlar iman etti, Firavun inkârda direndi. Yani delil herkeste aynı kanaati oluşturmadı.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Firavun hakikatle yüzleşince baskıyı artırdı → ulaşılır.</td></tr><tr class=\"ok\"><td>B</td><td>Herkes aynı kanaate varmadı → ulaşılamaz.</td></tr><tr><td>C</td><td>Ön yargısız sihirbazlar gerçeği kabul etti → ulaşılır.</td></tr><tr><td>D</td><td>Asanın sihri yutması hakkın batıla üstünlüğünü gösterir → ulaşılır.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Bir olayda farklı tepkiler varsa “ortak kanaat” ifadesi yanlıştır.</div><div class=\"sv-w\"><b>Tuzak:</b> B’deki “delillerin niteliği” ifadesi olumlu olduğu için doğru sanılabilir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 9. soru"
 },
 "mebi-din-y04-10": {
  "t": "din-kader",
  "a": "D",
  "o": 100059,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Mısır’ın en ünlü sihirbazları, Hz. Musa’nın asasının kendi uydurduklarını yuttuğunu görünce tehditlere rağmen secdeye kapandı.</li></ul><b>İstenen</b><p>Sihirbazların halktan daha hızlı ve kesin iman etmesinin nedeni.</p></div><ol class=\"sv-s\"><li><b>Neden sihirbazlar?</b> Sihrin bir aldatmaca olduğunu en iyi onlar bilir. Asanın yaptığının sihir olmadığını, insan gücüyle açıklanamayacağını hemen anladılar.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Dünyalık ödüllerden söz edilmiyor.</td></tr><tr><td>B</td><td>Toplumsal değişimi öngördükleri söylenmez.</td></tr><tr><td>C</td><td>Yeni güç odağı arayışı metinde yok.</td></tr><tr class=\"ok\"><td>D</td><td>Uzmanlıkları sayesinde olayın mucize olduğunu kavradılar → doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “En ünlü sihirbazlar” ifadesi uzmanlık ipucudur.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve C dünyevi gerekçelerdir; metin imanın samimi olduğunu, tehditlere rağmen secde edildiğini anlatır.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 10. soru"
 },
 "mebi-din-y04-11": {
  "t": "din-kader",
  "a": "C",
  "o": 100060,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Hz. Musa asasını vurunca deniz yarıldı ve inananlar kurtuldu.</li></ul><b>İstenen</b><p>Bu olayın açıklandığı İslami ilke.</p></div><ol class=\"sv-s\"><li><b>Mucizeyi düşün</b> Normalde deniz yarılmaz; bu, fiziksel yasaların dışına çıkan bir olaydır. Yasaları koyan Allah onları dilediği gibi değiştirebilir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Mucize, olağan işleyişin dışındadır; sünnetullah çerçevesinde açıklanmaz.</td></tr><tr><td>B</td><td>Toplumsal yasalarla ilgili değil.</td></tr><tr class=\"ok\"><td>C</td><td>Fiziksel yasalar Allah’ın sınırsız irade ve kudretine bağlıdır → mucize bunu gösterir.</td></tr><tr><td>D</td><td>Rızık ve ömür konusu değil.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Mucize = Allah’ın izniyle olağan yasaların dışında gerçekleşen olay.</div><div class=\"sv-w\"><b>Tuzak:</b> A’daki “sünnetullah” terimi tanıdık olduğu için seçilebilir; mucize ise tam tersine yasanın Allah’a bağlı olduğunu gösterir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 11. soru"
 },
 "mebi-din-y04-12": {
  "t": "din-kader",
  "a": "A",
  "o": 100061,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Allah, Hz. Musa ve Hz. Harun’a Firavun’a gidip ona yumuşak bir üslupla konuşmalarını, “ola ki aklını başına toplar veya içine bir korku düşer” diye emretti. (Taha, 43-44)</li></ul><b>İstenen</b><p>Zalim bir yöneticiye bile yumuşak üslupla yaklaşılmasının amacı.</p></div><ol class=\"sv-s\"><li><b>Ayetteki amaç ifadesi</b> “Ola ki aklını başına toplar” → yumuşak üslup, muhatabın düşünmesine ve öğüt almasına fırsat vermek içindir.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Nezaketle yaklaşıp gerçeği düşünmesine imkân tanımak → ayetteki amaç.</td></tr><tr><td>B</td><td>Dayanışma metinde var ama yumuşak üslubun amacı değil.</td></tr><tr><td>C</td><td>Sabır ve metanet bu emrin amacı olarak verilmez.</td></tr><tr><td>D</td><td>Besmele konuyla ilgisiz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Soru kökü “yumuşak üslubun amacı” diyor; cevap ayetteki “ola ki” ile başlayan kısımdadır.</div><div class=\"sv-w\"><b>Tuzak:</b> B metinde geçen bir bilgidir ama sorulan amaç bu değildir.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 12. soru"
 },
 "mebi-din-y04-13": {
  "t": "din-kader",
  "a": "B",
  "o": 100062,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Allah Hz. Musa’ya kullarını geceleyin çıkarıp denizde kuru bir yol açmasını, yakalanmaktan korkmamasını vahyetti (Taha, 77).</li><li>Firavun ordusuyla peşlerine düştü ama gücü ilahi takdir karşısında çaresiz kaldı.</li></ul><b>İstenen</b><p>Metinde anlatılmak istenen.</p></div><ol class=\"sv-s\"><li><b>Olayın özü</b> İsrailoğulları önünde deniz, arkasında ordu olan aşılmaz bir durumdaydı; Allah’a güvenip vahye uydular ve kurtuldular.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Metin liderlerin kararlarını değil, ilahi yardımı öne çıkarıyor.</td></tr><tr class=\"ok\"><td>B</td><td>İlahi yardıma güven aşılmaz engelleri aştırır → doğru.</td></tr><tr><td>C</td><td>Firavun’un gücünden söz edilir ama metnin ana fikri bu değildir.</td></tr><tr><td>D</td><td>Hazırlığın ön şart olduğu söylenmez; kurtuluş vahiyle oldu.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Korkmaksızın, endişe etmeksizin” ifadesi Allah’a güveni anlatır.</div><div class=\"sv-w\"><b>Tuzak:</b> C’de Firavun’un çaresizliği var ama ana vurgu inananların kurtuluşudur.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 13. soru"
 },
 "mebi-din-y04-14": {
  "t": "din-kader",
  "a": "B",
  "o": 100063,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Hz. Musa bir süreliğine kavminden ayrılıp yerine Hz. Harun’u bıraktı.</li><li>II. Bu süreçte halkın bir kısmı Samiri’nin etkisiyle yanlış inanca sürüklendi; Hz. Harun onları uyardı.</li><li>III. Hz. Musa döndüğünde verilen sözden dönülmesini sorguladı.</li></ul><b>İstenen</b><p>Bilgilerden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Olayın sırası</b> Rehber (Hz. Musa) ayrılınca halkın bir kısmı inancından saptı. Yani gerçek bağlılık, rehberlik ve denetimin zayıfladığı zamanda sınanır.</li><li><b>Diğer şıklar</b> Bilgilerde Firavun’dan kurtuluş ya da ortak tehdit anlatılmıyor; C ise Hz. Harun’un uyarılarının etkisini yorumlar, bilgiler bunu ölçmez.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Bilgilerde büyük zorluktan kurtuluş ayrıca anlatılmıyor; yorum gerekir.</td></tr><tr class=\"ok\"><td>B</td><td>Rehber ayrılınca sapma oldu → bağlılık bu dönemde sınanır.</td></tr><tr><td>C</td><td>Uyarının sınırlı etkisi kısmen sezilir ama bilgilerin ana sonucu değildir.</td></tr><tr><td>D</td><td>Firavun bilgilerde geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Öncüllere dayanan yargıyı seç; öncüllerde olmayan bilgiyi (Firavun, deniz) gerektiren şıkları ele.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve D kıssayı bilen için doğru görünür ama verilen üç bilgiden çıkmaz.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 4 · 14. soru"
 },
 "mebi-din-y05-1": {
  "t": "din-kader",
  "a": "C",
  "o": 100064,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Allah’ın kâinat üzerindeki hükümranlığına işaret edilir. II. Bütün işler Allah’ın izniyle gerçekleşir. III. İnsanların ilmi sınırsızdır. IV. Allah eksikliklerden uzaktır. V. İnsan nimetlere şükretmelidir.</li></ul><b>İstenen</b><p>Ayetelkürsi’nin mesajlarından olanlar.</p></div><ol class=\"sv-s\"><li><b>Ayetelkürsi’nin anlamını hatırla</b> Allah Hay ve Kayyum’dur; O’nu uyuklama ve uyku tutmaz (eksiksizlik); göklerde ve yerde ne varsa O’nundur (hükümranlık); izni olmadan kimse şefaat edemez (her şey O’nun izniyle); insanlar O’nun ilminden ancak dilediği kadarını kavrar; kürsüsü gökleri ve yeri kaplar.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>“Göklerde ve yerde ne varsa O’nundur” → var.</td></tr><tr><td>II</td><td>“O’nun izni olmadan…” → var.</td></tr><tr><td>III</td><td>Tersine insanın ilmi sınırlıdır → yok.</td></tr><tr><td>IV</td><td>“Uyuklama ve uyku tutmaz” → var.</td></tr><tr><td>V</td><td>Şükür Ayetelkürsi’de geçmez → yok.</td></tr><tr class=\"ok\"><td>C</td><td>I, II ve IV.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ayetelkürsi’nin ana teması tevhid ve Allah’ın sıfatlarıdır.</div><div class=\"sv-w\"><b>Tuzak:</b> V güzel bir öğüttür ama bu ayette yer almaz.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 1. soru"
 },
 "mebi-din-y05-2": {
  "t": "din-kader",
  "a": "A",
  "o": 100065,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Varlığı kendinden olan, yarattıklarına hâkim olan ve onları gözeten. II. Hayatı sürekli olan, diri. III. İzzet, şeref ve hükümranlık bakımından en yüce. IV. Zatının ve sıfatlarının ululuğu kavranamayacak kadar üstün.</li></ul><b>İstenen</b><p>Tanımlara karşılık gelen isimlerin doğru sıralaması.</p></div><ol class=\"sv-s\"><li><b>İsimleri eşleştir</b> I → <b>Kayyum</b> (her şeyi ayakta tutan, gözeten). II → <b>Hay</b> (diri). III → <b>Alî</b> (en yüce). IV → <b>Azîm</b> (ululuğu kavranamayan, en büyük).</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Kayyum - Hay - Alî - Azîm → doğru sıra.</td></tr><tr><td>B</td><td>İlk ikisi ters.</td></tr><tr><td>C</td><td>Alî ile Azîm ters.</td></tr><tr><td>D</td><td>Tamamen ters.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ayetelkürsi “Hay, Kayyum” ile başlar, “Alî, Azîm” ile biter.</div><div class=\"sv-w\"><b>Tuzak:</b> Alî (yücelik, hükümranlık) ile Azîm (büyüklük, kavranamazlık) birbirine çok yakındır; tanımdaki anahtar sözcüğe bak.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 2. soru"
 },
 "mebi-din-y05-3": {
  "t": "din-kader",
  "a": "B",
  "o": 100066,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Evrende fiziksel, biyolojik ve toplumsal yasalarla işleyen bir düzen vardır.</li><li>Ayetelkürsi’de Allah’ın ilmi ve kudretiyle varlıkları koruyup gözetmesinin kendisine ağır gelmediği bildirilir.</li></ul><b>İstenen</b><p>Doğanın düzeniyle ilgili bu mesajla aynı doğrultudaki yargı.</p></div><ol class=\"sv-s\"><li><b>Mesajı yaz</b> Evreni koruyan, gözeten ve düzenini sağlayan Allah’tır; düzen O’nun koyduğu yasalarla sürer.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İnsanın müdahalesinden söz edilmiyor.</td></tr><tr class=\"ok\"><td>B</td><td>Doğa Allah’ın koyduğu ölçü ve ilkelerle sürer → mesajla aynı doğrultuda.</td></tr><tr><td>C</td><td>Düzen insanların kararıyla işlemez.</td></tr><tr><td>D</td><td>Eşit imkân konuyla ilgisiz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Evrendeki yasalar = Allah’ın koyduğu ölçü (sünnetullah).</div><div class=\"sv-w\"><b>Tuzak:</b> A çevre bilinciyle ilgili doğru bir öğüt gibi görünür; ama ayetin mesajı değildir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 3. soru"
 },
 "mebi-din-y05-4": {
  "t": "din-kader",
  "a": "D",
  "o": 100067,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ayetelkürsi’de insanın yalnızca Allah’ın dilediği ölçüde bilgiye ulaşabildiği vurgulanır.</li></ul><b>İstenen</b><p>Bu durumun desteklediği yargı.</p></div><ol class=\"sv-s\"><li><b>İfadenin anlamı</b> Allah’ın ilmi her şeyi kuşatır; insana ise O’nun dilediği kadar, sınırlı bir bilgi verilmiştir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Doğru olabilir ama vurgu insan bilgisinin sınırlı oluşudur.</td></tr><tr><td>B</td><td>İfade bilginin kaynağını Allah’ın dilemesine bağlar; çaba vurgulanmaz.</td></tr><tr><td>C</td><td>Olayların gidişatı konusu değil.</td></tr><tr class=\"ok\"><td>D</td><td>Her şeyi kuşatan Allah insana sınırlı ilim vermiştir → tam karşılık.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Dilediği kadarını” ifadesi insan bilgisinin sınırlılığını gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> A “işe yarayan bilgi” der; ifade bilginin miktarını (sınırlılığını) vurgular.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 4. soru"
 },
 "mebi-din-y05-5": {
  "t": "din-kader",
  "a": "B",
  "o": 100068,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ayetelkürsi’de “Ne uykusu gelir ne de uyur.” ifadesi geçer.</li></ul><b>İstenen</b><p>Bu ifadeyle ilgili <b>söylenemeyecek</b> yargı.</p></div><ol class=\"sv-s\"><li><b>İfadenin anlamı</b> Uyku ve uyuklama insana özgü ihtiyaç ve zaaflardır. Allah bunlardan uzaktır; kâinatı her an gözetir ve yönetir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İnsani ihtiyaçlardan uzak olduğu vurgulanır → söylenir.</td></tr><tr class=\"ok\"><td>B</td><td>Yaratma gücü bu ifadede anlatılmaz → söylenemez.</td></tr><tr><td>C</td><td>Her an gözetim ve yönetim → söylenir.</td></tr><tr><td>D</td><td>Acziyet ve eksiklik sıfatlarıyla anılamaz → söylenir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Uyumamak = kesintisiz gözetim + eksiksizlik.</div><div class=\"sv-w\"><b>Tuzak:</b> B, Allah için doğru bir bilgidir; ama bu ifadenin içeriği değildir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 5. soru"
 },
 "mebi-din-y05-6": {
  "t": "din-kader",
  "a": "D",
  "o": 100069,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Farz namazın ardından Ayetelkürsi’yi okuyan kimse, sonraki namaza kadar Allah’ın himayesi altındadır.” (Hadis)</li></ul><b>İstenen</b><p>Hadise göre <b>söylenemeyecek</b> yargı.</p></div><ol class=\"sv-s\"><li><b>Hadisin içeriği</b> Okuma zamanı: farz namazlardan sonra. Sonuç: Allah’ın koruması.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Günde beş kez okununca Allah’ın yüceliği hatırlanır → söylenir.</td></tr><tr><td>B</td><td>Namazlardan sonra okunması tavsiye edilir → söylenir.</td></tr><tr><td>C</td><td>İlahi koruma altında olur → söylenir.</td></tr><tr class=\"ok\"><td>D</td><td>Günahların bağışlanması hadiste geçmez → söylenemez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Hadiste “himaye” (koruma) geçiyor; bağışlanma değil.</div><div class=\"sv-w\"><b>Tuzak:</b> D dinî açıdan güzel bir müjde gibi durur; hadiste yoksa seçme.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 6. soru"
 },
 "mebi-din-y05-7": {
  "t": "din-kader",
  "a": "A",
  "o": 100070,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Kâinattaki olayların Allah’ın ilmi, iradesi, kudreti ve izniyle gerçekleştiği Ayetelkürsi’de belirtilmiştir.</li></ul><b>İstenen</b><p>Bu durumun desteklediği davranış.</p></div><ol class=\"sv-s\"><li><b>İnançtan davranışa</b> Her şey Allah’ın izniyle oluyorsa insan elinden geleni yapar, sonucu O’na bırakır. Bu, <b>tevekküldür</b>.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Önce tedbir, sonra sonucu Allah’a emanet → tevekkül.</td></tr><tr><td>B</td><td>Her işin yalnız gayretle aşılacağı düşüncesi sonucu insana bağlar.</td></tr><tr><td>C</td><td>Planlamanın sonucu belirlediği düşüncesi Allah’ın iznini yok sayar.</td></tr><tr><td>D</td><td>İnsanların beğenisi konuyla ilgisiz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Allah’ın izniyle olur” inancı → tedbir + tevekkül.</div><div class=\"sv-w\"><b>Tuzak:</b> B olumlu bir tutumdur ama sonucu yalnızca insanın çabasına bağlar.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 7. soru"
 },
 "mebi-din-y05-8": {
  "t": "din-kader",
  "a": "C",
  "o": 100071,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ayetelkürsi’nin son kısmında “Onları korumak kendisine zor gelmez.” ifadesi yer alır.</li></ul><b>İstenen</b><p>Bu ifadeyle vurgulanan.</p></div><ol class=\"sv-s\"><li><b>İfadenin anlamı</b> Gökleri ve yeri korumak, idare etmek Allah için hiç zor değildir. Bu, sınırsız kudreti anlatır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İnsanın görevi değil, Allah’ın kudreti anlatılıyor.</td></tr><tr><td>B</td><td>Tam tersine Allah yarattıklarını korur.</td></tr><tr class=\"ok\"><td>C</td><td>Allah’ın kudreti ve kâinatı idare etmedeki kolaylığı → doğru.</td></tr><tr><td>D</td><td>Zor zamanlarda Allah’ı anmak ifadede geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Zor gelmez” = sınırsız kudret.</div><div class=\"sv-w\"><b>Tuzak:</b> B ifadeyi tersine çevirir; “korumak” sözcüğünü dikkatle oku.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 5 · 8. soru"
 },
 "mebi-din-y06-1": {
  "t": "din-zekat",
  "a": "D",
  "o": 100072,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam, insanın yalnız kendi ihtiyaçlarını değil, çevresindekilerin ihtiyaçlarını da gözetmesini ister.</li><li>Bu anlayış, kişinin imkânlarını başkalarının yararına da kullanmasını teşvik eder.</li></ul><b>İstenen</b><p>Metinden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Metnin dengesi</b> “Sadece kendi ihtiyaçlarını değil… da” yapısı, kişinin hem kendini hem toplumu birlikte düşünmesi gerektiğini anlatır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Eşit paylaşım zorunluluğundan söz edilmez.</td></tr><tr><td>B</td><td>Zaman sınırı metinde yok.</td></tr><tr><td>C</td><td>Metin bireyin görevinden söz ediyor, toplumun görevinden değil.</td></tr><tr class=\"ok\"><td>D</td><td>Bireysel ve toplumsal ihtiyaçların birlikte gözetilmesi → metnin özeti.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Değil… de” bağlacı iki şeyin birlikte geçerli olduğunu gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> A, paylaşmayı aşırı genelleştirir; metin “eşit” paylaşımdan söz etmez.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 1. soru"
 },
 "mebi-din-y06-2": {
  "t": "din-zekat",
  "a": "B",
  "o": 100073,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam’ın paylaşma ve yardımlaşmaya verdiği önemle ilişkilendirilemeyen davranış soruluyor.</li></ul><b>İstenen</b><p>İlişkilendirilemeyen davranış.</p></div><ol class=\"sv-s\"><li><b>İslam’ın yardım ahlakı</b> Yardım Allah rızası için yapılır; gösterişten (riya) uzak olmalı, mümkünse gizli yapılmalıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Komşunun sıkıntısını gidermek → yardımlaşma.</td></tr><tr class=\"ok\"><td>B</td><td>Yardımı herkese göstermek gösteriştir; İslam’ın yardım anlayışıyla bağdaşmaz.</td></tr><tr><td>C</td><td>Maddi ve manevi destek → yardımlaşma.</td></tr><tr><td>D</td><td>Gönüllü toplumsal çalışma → yardımlaşma.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Yardımın değeri niyettedir; gösteriş sevabı yok eder.</div><div class=\"sv-w\"><b>Tuzak:</b> B’de yardım var gibi görünür; sorun yardımın kendisi değil, gösterilmesidir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 2. soru"
 },
 "mebi-din-y06-3": {
  "t": "din-zekat",
  "a": "A",
  "o": 100074,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“… İyilik ve takva hususunda yardımlaşın, günah ve haksızlık yolunda yardımlaşmayın…” (Maide, 2)</li></ul><b>İstenen</b><p>Metinde vurgulanan.</p></div><ol class=\"sv-s\"><li><b>Ayetin emri</b> Hayırlı işlerde birlikte hareket edin, kötülükte birlikte hareket etmeyin.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Faydalı işlerde birlikte hareket → ayetin vurgusu.</td></tr><tr><td>B</td><td>İyiliğin fark edilmesi ayette yok; tam tersine gösteriş istenmez.</td></tr><tr><td>C</td><td>Zaman sınırı yok.</td></tr><tr><td>D</td><td>Ayet herkese hitap eder; yalnız zenginlere değil.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Maide 2 = iyilikte yardımlaş, kötülükte yardımlaşma.</div><div class=\"sv-w\"><b>Tuzak:</b> D yardımla ilgili doğru bir fikir gibi görünür ama ayette sınıf ayrımı yok.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 3. soru"
 },
 "mebi-din-y06-4": {
  "t": "din-zekat",
  "a": "A",
  "o": 100075,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Mahalle halkı ihtiyaç sahibi bir aile için aralarında yardım toplayıp temel ihtiyaçlarını karşılıyor.</li></ul><b>İstenen</b><p>Bu durumla doğrudan ilişkili kavram.</p></div><ol class=\"sv-s\"><li><b>Durumun özü</b> Bir topluluk birlik olup ihtiyaç sahibine destek oluyor. Birlikte hareket edip yardımlaşmak <b>dayanışmadır</b>.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Dayanışma → topluluğun birlikte yardım etmesi.</td></tr><tr><td>B</td><td>Fedakârlık kişinin kendi isteğinden vazgeçmesidir; metinde vurgulanmaz.</td></tr><tr><td>C</td><td>Merhamet duygudur; metin birlikte yapılan eylemi anlatır.</td></tr><tr><td>D</td><td>Özveri fedakârlığın eş anlamlısıdır.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Aralarında toplayarak” ifadesi birlikte hareketi, yani dayanışmayı gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> B ve D eş anlamlıdır; ikisi birden doğru olamayacağı için ikisini de ele.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 4. soru"
 },
 "mebi-din-y06-5": {
  "t": "din-zekat",
  "a": "B",
  "o": 100076,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam’da paylaşma yalnız maddi yardımla sınırlı değildir; bilgi, emek ve zaman da paylaşılabilir.</li></ul><b>İstenen</b><p>Bu anlayışa örnek <b>gösterilemeyecek</b> davranış.</p></div><ol class=\"sv-s\"><li><b>Örnek türü</b> Soru bilgi, emek ve zaman paylaşımını istiyor; yani maddi olmayan yardımları.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Derste yardım → bilgi paylaşımı.</td></tr><tr class=\"ok\"><td>B</td><td>Okul masraflarını üstlenmek → maddi yardım; örnek gösterilemez.</td></tr><tr><td>C</td><td>Ev işlerine destek → emek paylaşımı.</td></tr><tr><td>D</td><td>Hasta ziyareti → zaman ve manevi destek.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Yalnız maddi değildir” diyen metinde cevap çoğu zaman maddi yardım örneğidir.</div><div class=\"sv-w\"><b>Tuzak:</b> B de güzel bir yardımdır; ama metnin istediği maddi olmayan paylaşım değildir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 5. soru"
 },
 "mebi-din-y06-6": {
  "t": "din-zekat",
  "a": "D",
  "o": 100077,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Kim bir Müslüman’ın dünya sıkıntılarından birini giderirse Allah da onun kıyamet günündeki sıkıntılarından birini giderir. Kim darda kalanın işini kolaylaştırırsa Allah da dünya ve ahirette onun işlerini kolaylaştırır…” (Hadis)</li></ul><b>İstenen</b><p>Metinde vurgulanan.</p></div><ol class=\"sv-s\"><li><b>Hadisin yapısı</b> “Kim yardım ederse → Allah da ona yardım eder.” Yardım edenin karşılığını Allah verir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ahiret geçer ama toplumsal sorunlara etkisi konu edilmez.</td></tr><tr><td>B</td><td>Kişisel problemlere öncelik yok; tersine başkasının sıkıntısı öne çıkıyor.</td></tr><tr><td>C</td><td>Hadis maddi imkân şartı koymaz.</td></tr><tr class=\"ok\"><td>D</td><td>Yardım eden kişiyi Allah gözetir, işini kolaylaştırır → vurgu.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Kim… Allah da…” kalıbı karşılık/ödül vurgusudur.</div><div class=\"sv-w\"><b>Tuzak:</b> A’daki “ahiret” sözcüğü hadiste geçtiği için çekici gelir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 6. soru"
 },
 "mebi-din-y06-7": {
  "t": "din-zekat",
  "a": "C",
  "o": 100078,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam insanı cimrilik ve bencillikten kurtarıp paylaşmanın mutluluğuna ulaştırmayı hedefler.</li></ul><b>İstenen</b><p>Yardımlaşmanın birey açısından vurgulanan yönü.</p></div><ol class=\"sv-s\"><li><b>Metindeki kazanım</b> Cimrilik ve bencillikten kurtulmak karakterin gelişmesidir; paylaşmanın mutluluğu iç huzurdur.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Saygın konum metinde yok.</td></tr><tr><td>B</td><td>Malın azalmasını engellemek metinde yok.</td></tr><tr class=\"ok\"><td>C</td><td>Karakter gelişimi ve iç huzur → metnin vurgusu.</td></tr><tr><td>D</td><td>Etki ve güç sahibi olmak metinle ilgisiz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Kötü huydan kurtulma = karakter gelişimi; mutluluk = iç huzur.</div><div class=\"sv-w\"><b>Tuzak:</b> A ve D dünyevi kazançlardır; metin manevi kazancı anlatıyor.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 7. soru"
 },
 "mebi-din-y06-8": {
  "t": "din-zekat",
  "a": "C",
  "o": 100079,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Kişi zalim de olsa, mazlum da olsa din kardeşine yardım etsin. Kardeşi zalimse onu engellesin; çünkü zalimi yaptığı işten döndürmek ona yapılacak bir yardımdır…” (Hadis)</li></ul><b>İstenen</b><p>Hadisten “yardım” kavramıyla ilgili ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Hadisin ilginç yanı</b> Zalime yardım, onu desteklemek değil, zulmünden alıkoymaktır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Öncelik sırası hadiste yok.</td></tr><tr><td>B</td><td>Hataları örtmek değil, engellemek isteniyor.</td></tr><tr class=\"ok\"><td>C</td><td>Kişiyi hatasından alıkoymak ona yardımdır → hadisin özü.</td></tr><tr><td>D</td><td>Zarar vermemek hadiste geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Yardım yalnız vermek değildir; yanlıştan alıkoymak da yardımdır.</div><div class=\"sv-w\"><b>Tuzak:</b> B, “zalimi korumak” gibi yanlış bir yardım anlayışıdır.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 8. soru"
 },
 "mebi-din-y06-9": {
  "t": "din-zekat",
  "a": "A",
  "o": 100080,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Allah yolunda sevdiğiniz şeylerden harcamadıkça iyiliğe asla eremezsiniz…” (Âl-i İmrân, 92)</li></ul><b>İstenen</b><p>Ayete göre gerçek iyiliğin ölçütü.</p></div><ol class=\"sv-s\"><li><b>Anahtar ifade</b> “Sevdiğiniz şeylerden” → gerçek iyilik, kişinin kendisi için değerli olandan vermesidir.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Paylaşılanın sahibi için değerli olması → ayetin ölçütü.</td></tr><tr><td>B</td><td>İhtiyaç gidermek önemlidir ama ayetin ölçütü değildir.</td></tr><tr><td>C</td><td>Piyasa değeri değil, kişi için değeri önemlidir.</td></tr><tr><td>D</td><td>Hız ayette geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Sevdiğinden vermek” = fedakârlık; iyiliğin ölçüsü budur.</div><div class=\"sv-w\"><b>Tuzak:</b> C, “değerli” sözcüğünü parayla karıştırır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 9. soru"
 },
 "mebi-din-y06-10": {
  "t": "din-zekat",
  "a": "D",
  "o": 100081,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Müminler birbirlerini sevmede, merhamet ve şefkatte bir organı rahatsızlanınca diğer organları da bu acıyı paylaşan bir bedene benzer.” (Hadis)</li></ul><b>İstenen</b><p>Hadisten ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Benzetmeyi çöz</b> Bir organın acısını bütün beden hisseder → toplumda birinin sıkıntısını herkes paylaşmalıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Hadis tek başına çözmeyi değil, birlikte paylaşmayı anlatır.</td></tr><tr><td>B</td><td>Güven hadisin konusu değil.</td></tr><tr><td>C</td><td>Farklı sorumluluklar hadiste yok.</td></tr><tr class=\"ok\"><td>D</td><td>Bireylerin birbirinin sıkıntısına duyarlı olması → benzetmenin anlamı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Tek beden” benzetmesi = duyarlılık ve dayanışma.</div><div class=\"sv-w\"><b>Tuzak:</b> C, organların farklı görevleri olduğunu düşündürür; hadis görevleri değil acıyı paylaşmayı anlatır.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 10. soru"
 },
 "mebi-din-y06-11": {
  "t": "din-zekat",
  "a": "A",
  "o": 100082,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam insanın ve toplumun yararına işlerde yardımlaşmayı teşvik eder; zararlı davranışlarda birlikte hareketi uygun görmez.</li></ul><b>İstenen</b><p>Bu cümlede sözü edilen <b>yararlı yardımlaşmaya</b> örnek gösterilemeyecek davranış.</p></div><ol class=\"sv-s\"><li><b>Yararlı mı, zararlı mı?</b> Afet yardımı, yaşlılara destek, yardım kampanyası toplumun yararınadır. Anlaşmazlıkta haklı-haksız bakmadan arkadaşın tarafını tutmak ise haksızlığa ortak olmaktır.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Taraf tutmak haksızlığa destek olabilir → örnek gösterilemez.</td></tr><tr><td>B</td><td>Afet yardımı → yararlı.</td></tr><tr><td>C</td><td>Yaşlılara yardım → yararlı.</td></tr><tr><td>D</td><td>Yardım kampanyası → yararlı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Maide 2: “Günah ve haksızlıkta yardımlaşmayın.”</div><div class=\"sv-w\"><b>Tuzak:</b> A’da “arkadaşa destek” iyi bir davranış gibi görünür; ama ölçüt haklılık olmalıdır.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 11. soru"
 },
 "mebi-din-y06-12": {
  "t": "din-zekat",
  "a": "B",
  "o": 100083,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İnsan hayatını ancak başkalarıyla dayanışma içinde sürdürebilir; herkes diğerlerinin emeğine ve desteğine muhtaçtır.</li></ul><b>İstenen</b><p>Metni destekleyen yargı.</p></div><ol class=\"sv-s\"><li><b>Metnin ana fikri</b> “Ancak” sözcüğü dayanışmanın zorunlu olduğunu gösterir → yardımlaşma vazgeçilmezdir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Metin bağımsız karar almaktan söz etmez.</td></tr><tr class=\"ok\"><td>B</td><td>Yardımlaşma vazgeçilmez bir gerekliliktir → ana fikir.</td></tr><tr><td>C</td><td>Metne terstir; ihtiyaçlar başkalarının desteğiyle karşılanır.</td></tr><tr><td>D</td><td>Emek geçiyor ama metin emeğe saygıyı değil, birbirine muhtaçlığı anlatıyor.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Ancak … ile sürdürebilir” = olmazsa olmaz.</div><div class=\"sv-w\"><b>Tuzak:</b> D, metinde geçen “emek” sözcüğüne dayanan çeldiricidir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 12. soru"
 },
 "mebi-din-y06-13": {
  "t": "din-zekat",
  "a": "B",
  "o": 100084,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Yardımlaşmanın güçlü olduğu ortamlarda bireyler kendini güvende hisseder, sosyal ilişkiler sağlıklı olur.</li></ul><b>İstenen</b><p>Metinden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Sebep–sonuç</b> Sebep: yardımlaşma (dayanışma). Sonuç: güven + sağlıklı ilişkiler = toplumsal huzur ve düzen.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Metin güveni bireysel çabaya değil, yardımlaşmaya bağlar.</td></tr><tr class=\"ok\"><td>B</td><td>Dayanışma toplumsal huzuru ve düzeni güçlendirir → doğru.</td></tr><tr><td>C</td><td>Kişisel tercihlerden söz edilmez.</td></tr><tr><td>D</td><td>Refah (ekonomik zenginlik) metinde yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Sonuçtaki “güven” ve “sağlıklı ilişki” sözcüklerini kapsayan şık “huzur ve düzen”dir.</div><div class=\"sv-w\"><b>Tuzak:</b> D’deki “refah” sözcüğü metinde olmayan ekonomik bir anlam taşır.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 13. soru"
 },
 "mebi-din-y06-14": {
  "t": "din-zekat",
  "a": "C",
  "o": 100085,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Nisa 36: Anne-babaya, akrabaya, yetimlere, yoksullara, komşulara, arkadaşa, yolcuya iyi davranın.</li><li>Allah yardımlaşmanın yakın çevreden başlamasını tavsiye eder; çevresine sorumluluk bilinci gelişmeyen kişinin topluma faydalı olması güçleşir.</li></ul><b>İstenen</b><p>Metinden ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Metnin son cümlesi</b> Toplumsal fayda, yakın çevreye karşı sorumlulukla başlar.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Ayet kime yardım edileceğini sıralamıştır; kişisel tercihe bırakılmamıştır.</td></tr><tr><td>B</td><td>Doğru bir genel yargı ama metnin özel vurgusu değil.</td></tr><tr class=\"ok\"><td>C</td><td>Toplumsal sorumluluk çevreye karşı görevlerle başlar → metnin ana fikri.</td></tr><tr><td>D</td><td>Doğru bir genel yargı ama metinde sorun çözümünden söz edilmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Yakın çevreden başlar” ifadesi C’nin “çevresine karşı görevleriyle başlar” ifadesiyle örtüşür.</div><div class=\"sv-w\"><b>Tuzak:</b> B ve D de yardımlaşmayla ilgili doğru cümlelerdir; metne özgü değildir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 14. soru"
 },
 "mebi-din-y06-15": {
  "t": "din-zekat",
  "a": "D",
  "o": 100086,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Merhametlilere Rahman merhamet eder. Siz yeryüzündekilere merhamet edin ki gökyüzündekiler de size merhamet etsin.” (Hadis)</li></ul><b>İstenen</b><p>Hadisten merhametle ilgili ulaşılabilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Anahtar ifade</b> “Yeryüzündekiler” → insan, hayvan, bitki, yeryüzündeki her şey. Merhamet sınırlı değildir.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Yalnız muhtaçlarla sınırlamak hadisteki genişliği daraltır.</td></tr><tr><td>B</td><td>Belirli bir inançla sınırlanmaz.</td></tr><tr><td>C</td><td>Sosyal statü ölçüt değildir.</td></tr><tr class=\"ok\"><td>D</td><td>Doğadaki tüm varlıkları kapsar → “yeryüzündekiler”.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Hadiste “insanlara” değil “yeryüzündekilere” denmesi kapsamın genişliğini gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> A, B ve C merhameti daraltır; geniş kapsamlı ifade seçilmeli.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 6 · 15. soru"
 },
 "mebi-din-y07-1": {
  "t": "din-zekat",
  "a": "D",
  "o": 100087,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Dinen zengin sayılan Müslümanların mallarının belli bir kısmını ibadet niyetiyle ihtiyaç sahiplerine vermesi.</li><li>II. Ramazanda bayramdan önce verilmesi gereken; sağlığın ve orucu tamamlamanın şükrü olan sadaka.</li><li>III. Allah rızası için yapılan hayırlı işlerin tamamı.</li><li>IV. Allah rızası için yapılan farz ve vacip tüm harcamalar.</li></ul><b>İstenen</b><p>Tanımların kavramlarının doğru sıralaması.</p></div><ol class=\"sv-s\"><li><b>Tanımları eşleştir</b> I → <b>zekât</b> (zengin, malın belli kısmı). II → <b>fitre</b> (ramazan, bayramdan önce). III → <b>sadaka</b> (her türlü hayır). IV → <b>infak</b> (Allah yolunda harcama).</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Sıra Fitre–Zekât–İnfak–Sadaka; ilk ikisi ters.</td></tr><tr><td>B</td><td>Tamamen karışık.</td></tr><tr><td>C</td><td>Tamamen karışık.</td></tr><tr class=\"ok\"><td>D</td><td>Zekât–Fitre–Sadaka–İnfak → doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ramazan + bayramdan önce = fitre; nisap + malın kırkta biri = zekât.</div><div class=\"sv-w\"><b>Tuzak:</b> Sadaka ve infakı karıştırma: sadaka her türlü iyilik, infak maddi harcamadır.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 1. soru"
 },
 "mebi-din-y07-2": {
  "t": "din-zekat",
  "a": "D",
  "o": 100088,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tablo: I. Küçükbaş hayvanlar {{1|40}}; II. Madenler {{1|5}}; III. Nakit para {{1|40}}; IV. Toprak ürünleri {{1|15}}.</li></ul><b>İstenen</b><p>Oranı yanlış verilen mal.</p></div><ol class=\"sv-s\"><li><b>Zekât oranlarını hatırla</b> Nakit para, ticaret malı, altın-gümüş → {{1|40}}. Küçükbaş (40 koyunda 1) → {{1|40}}. Madenler (define, maden) → {{1|5}}. Toprak ürünleri (öşür) → masrafsız sulanan {{1|10}}, masraflı sulanan {{1|20}}.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>{{1|40}} → doğru.</td></tr><tr><td>II</td><td>{{1|5}} → doğru.</td></tr><tr><td>III</td><td>{{1|40}} → doğru.</td></tr><tr><td>IV</td><td>Toprak ürünlerinde oran {{1|10}} veya {{1|20}} olur; {{1|15}} yanlış.</td></tr><tr class=\"ok\"><td>D</td><td>IV.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Toprak ürününün zekâtına öşür denir; “öşür” onda bir demektir.</div><div class=\"sv-w\"><b>Tuzak:</b> Madenlerde {{1|5}} oranı alışılmadık geldiği için yanlış sanılabilir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 2. soru"
 },
 "mebi-din-y07-3": {
  "t": "din-zekat",
  "a": "C",
  "o": 100089,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Ali ramazanda, bir kişinin günlük yemek masrafı kadar parayı ailesindeki her birey adına yoksul bir komşusuna verdi.</li></ul><b>İstenen</b><p>Sözü edilen vacip ibadet.</p></div><ol class=\"sv-s\"><li><b>İpuçları</b> Ramazan ayı + kişi başı günlük yiyecek bedeli + aile fertleri adına → <b>fitre</b> (fıtır sadakası).</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Adak, bir dileğin gerçekleşmesi için verilen sözdür.</td></tr><tr><td>B</td><td>Fidye, oruç tutamayanın her gün için verdiği bedeldir; Ali oruçla ilgili bir eksiği telafi etmiyor.</td></tr><tr class=\"ok\"><td>C</td><td>Fitre → ramazanda aile fertleri adına verilen vacip sadaka.</td></tr><tr><td>D</td><td>Zekât, nisap miktarı malın kırkta biridir; kişi başı hesaplanmaz.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Her birey adına” ifadesi fitrenin aile fertleri için ayrı ayrı verildiğini gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> Fidye de günlük yemek bedeli kadardır; ama fidye orucu tutamayan kişi için verilir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 3. soru"
 },
 "mebi-din-y07-4": {
  "t": "din-zekat",
  "a": "D",
  "o": 100090,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tevbe 60: Zekât yoksullara, düşkünlere, zekât memurlarına, kalpleri kazanılacak olanlara, köle azadına, borçlulara, Allah yolunda olanlara ve yolda kalmışlara verilir.</li></ul><b>İstenen</b><p>Ayette sayılan gruplardan biri <b>olmayan</b>.</p></div><ol class=\"sv-s\"><li><b>Şıkları ayetle eşleştir</b> Temel ihtiyacını karşılayamayan → yoksul. Kalbi İslam’a ısındırılmak istenen → kalpleri kazanılacak olanlar. Parasız kalan yolcu → yolda kalmış.</li><li><b>Anne-baba</b> Kişi kendi anne-babasına, çocuklarına ve eşine zekât veremez; çünkü onların bakımı zaten görevidir. Ayette de sayılmazlar.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Yoksullar → ayette var.</td></tr><tr><td>B</td><td>Kalpleri kazanılacak olanlar → ayette var.</td></tr><tr><td>C</td><td>Yolda kalmışlar → ayette var.</td></tr><tr class=\"ok\"><td>D</td><td>Anne-baba ayette yok; ayrıca zekât onlara verilmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Zekât verilemeyenler: anne-baba, dede-nine, çocuklar, torunlar, eş.</div><div class=\"sv-w\"><b>Tuzak:</b> “Zor durumda” ifadesi onları yoksul grubuna sokar gibi görünse de anne-babaya zekât verilmez.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 4. soru"
 },
 "mebi-din-y07-5": {
  "t": "din-zekat",
  "a": "C",
  "o": 100091,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekât, toplumda zenginle fakir arasında bir köprü olarak nitelendirilir.</li></ul><b>İstenen</b><p>Zekâtın toplumsal işlevlerinden biri.</p></div><ol class=\"sv-s\"><li><b>“Köprü” benzetmesi</b> Zenginle fakiri birbirine yaklaştırır; aralarındaki kıskançlık, kin gibi olumsuz duyguları azaltır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Zekât otorite kurmak için değildir.</td></tr><tr><td>B</td><td>Zekât çalışma ihtiyacını ortadan kaldırmaz.</td></tr><tr class=\"ok\"><td>C</td><td>Sınıf farklarından doğan olumsuz duyguları önler → köprü işlevi.</td></tr><tr><td>D</td><td>Devletin görevini zenginlere yüklemek zekâtın amacı değildir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Zekât = toplumsal barış ve kardeşlik köprüsü.</div><div class=\"sv-w\"><b>Tuzak:</b> B ve D zekâtın işlevini abartan yanlış genellemelerdir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 5. soru"
 },
 "mebi-din-y07-6": {
  "t": "din-zekat",
  "a": "B",
  "o": 100092,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tanım: Allah’ın hoşnutluğunu elde etmek için kişinin kendi servetinden maddi harcama yapması ve muhtaçlara yardım etmesi.</li></ul><b>İstenen</b><p>Bu tanımın ait olduğu kavram.</p></div><ol class=\"sv-s\"><li><b>Kavramları ayır</b> Zekât belirli oranlı farz ibadettir. Fitre ramazanda verilen vaciptir. Sadaka maddi-manevi her iyiliktir. <b>İnfak</b>, Allah rızası için yapılan maddi harcamadır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Fitre ramazana özgüdür.</td></tr><tr class=\"ok\"><td>B</td><td>İnfak → Allah rızası için maddi harcama.</td></tr><tr><td>C</td><td>Sadaka maddi olmak zorunda değildir.</td></tr><tr><td>D</td><td>Zekâtın oranı, nisabı, zamanı bellidir; tanımda bunlar yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tanımdaki “maddi harcama” ve “servetinden” sözcükleri infakı gösterir.</div><div class=\"sv-w\"><b>Tuzak:</b> Sadaka da yardımdır; ama manevi iyilikleri de kapsadığı için tanıma tam uymaz.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 6. soru"
 },
 "mebi-din-y07-7": {
  "t": "din-zekat",
  "a": "B",
  "o": 100093,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Toprak ürünlerinde zekât oranı emek ve masrafa göre belirlenir: yağmurla sulanan arazide {{1|10}}, sulama ve masraf gerektiren arazide {{1|20}}.</li></ul><b>İstenen</b><p>{{1|20}} oranının uygulanma sebebi.</p></div><ol class=\"sv-s\"><li><b>Oranın mantığı</b> Üretici masraf yapmışsa zekât oranı yarıya iner. Böylece emek ve para harcayan kişinin yükü hafifler; zekât veren mali açıdan korunur.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Satış fiyatıyla ilgili bilgi yok.</td></tr><tr class=\"ok\"><td>B</td><td>Masraf yapan zekât yükümlüsünün korunması → doğru.</td></tr><tr><td>C</td><td>Verim düşüklüğü metinde geçmez.</td></tr><tr><td>D</td><td>Teşvik amacından söz edilmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Masraf arttıkça oran düşer: emek ve harcama gözetilir.</div><div class=\"sv-w\"><b>Tuzak:</b> D mantıklı bir ekonomik gerekçe gibi görünür ama metnin ölçütü “harcanan emek ve masraf”tır.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 7. soru"
 },
 "mebi-din-y07-8": {
  "t": "din-zekat",
  "a": "B",
  "o": 100094,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>I. Yılda bir kere verilir. II. Kimlere verileceği ayetle belirlenmiştir. III. Ramazan ayında verilmesi gerekir. IV. İstenilen kişiye verilebilir.</li></ul><b>İstenen</b><p>Zekâtla ilgili yanlış ifadeler.</p></div><ol class=\"sv-s\"><li><b>Her ifadeyi sına</b> I: Nisap miktarı mal üzerinden bir yıl geçince verilir → doğru. II: Tevbe 60’ta sayılmıştır → doğru. III: Zekâtın ramazanda verilme zorunluluğu yoktur; ramazanda verilmesi zorunlu olan fitredir → yanlış. IV: Zekât ayette sayılan kişilere verilir; herkese değil → yanlış.</li></ol><table class=\"sv-c\"><tr><td>I</td><td>Doğru.</td></tr><tr><td>II</td><td>Doğru.</td></tr><tr><td>III</td><td>Yanlış (fitreyle karışıyor).</td></tr><tr><td>IV</td><td>Yanlış (Tevbe 60).</td></tr><tr class=\"ok\"><td>B</td><td>III ve IV.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Zekâtın zamanı “bir yıl dolunca”dır; birçok kişi ramazanda verse de bu zorunlu değildir.</div><div class=\"sv-w\"><b>Tuzak:</b> Halk arasında zekâtın ramazanda verilmesi yaygın olduğu için III doğru sanılabilir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 8. soru"
 },
 "mebi-din-y07-9": {
  "t": "din-zekat",
  "a": "D",
  "o": 100095,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“İnsan ölünce şu üçü dışında amellerinin sevabı kesilir: sadaka-i câriye (faydası süregelen hayır), faydalanılan ilim, arkasından dua eden hayırlı evlat.” (Hadis)</li></ul><b>İstenen</b><p>Hadiste sözü edilen ibadetlerden biri.</p></div><ol class=\"sv-s\"><li><b>Sadaka-i câriye</b> Faydası kişi öldükten sonra da süren hayırdır: cami, okul, kütüphane, çeşme, hastane yaptırmak.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Yemek ısmarlamak bir defalık yardımdır.</td></tr><tr><td>B</td><td>Bilet almak bir defalık yardımdır.</td></tr><tr><td>C</td><td>Harçlık vermek bir defalık yardımdır.</td></tr><tr class=\"ok\"><td>D</td><td>Kütüphane yaptırmak → faydası süren hayır (sadaka-i câriye).</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Câriye = akan, süren. Kalıcı eser = sadaka-i câriye.</div><div class=\"sv-w\"><b>Tuzak:</b> A, B, C de sadakadır; ama faydaları kalıcı değildir.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 9. soru"
 },
 "mebi-din-y07-10": {
  "t": "din-zekat",
  "a": "A",
  "o": 100096,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekât, sadaka ve infakla ilgili bilgiler veriliyor.</li></ul><b>İstenen</b><p>Yanlış olan bilgi.</p></div><ol class=\"sv-s\"><li><b>Nisap kimin şartı?</b> Nisap, zekâtla yükümlü olmak için gereken asgari zenginliktir. Sadaka ise herkes tarafından, istenen miktarda verilebilir; nisap şartı yoktur.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Sadaka nisaba bağlı değildir → yanlış bilgi.</td></tr><tr><td>B</td><td>Zekâtın miktarı ve zamanı bellidir → doğru.</td></tr><tr><td>C</td><td>Sadaka maddi ve manevi iyilikleri kapsar → doğru.</td></tr><tr><td>D</td><td>İnfak Allah rızası için harcamadır → doğru.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Nisap yalnız zekât (ve kurban, fitre yükümlülüğü) için aranır; sadakada aranmaz.</div><div class=\"sv-w\"><b>Tuzak:</b> A cümlesinin zekât kısmı doğrudur; “ve sadaka” eklemesi cümleyi yanlış yapar.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 10. soru"
 },
 "mebi-din-y07-11": {
  "t": "din-zekat",
  "a": "B",
  "o": 100097,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>İslam paylaşmanın sadece zenginlere has olmadığını vurgular.</li></ul><b>İstenen</b><p>Bu cümleyi destekleyen.</p></div><ol class=\"sv-s\"><li><b>Kim verebilir?</b> Zekât yalnız zenginlere farzdır. Sadaka ise herkesin yapabileceği bir iyiliktir; bir tebessüm, güzel söz bile sadakadır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Zekât yalnız zenginleri ilgilendirir; cümleyi desteklemez.</td></tr><tr class=\"ok\"><td>B</td><td>Sadakanın herkesçe verilebilmesi → paylaşma herkese açıktır.</td></tr><tr><td>C</td><td>Böyle bir dinî düzenleme yok; ayrıca konu sadaka ve paylaşma.</td></tr><tr><td>D</td><td>Zekât miktarını her yıl artırma zorunluluğu yok.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Zekât zengine, sadaka herkese.</div><div class=\"sv-w\"><b>Tuzak:</b> A da paylaşmayla ilgilidir ama zengine özgü olduğu için cümlenin tersini destekler.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 11. soru"
 },
 "mebi-din-y07-12": {
  "t": "din-zekat",
  "a": "A",
  "o": 100098,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekât ve sadaka bireyde toplumsal sorumluluk bilincini geliştirir.</li></ul><b>İstenen</b><p>Zekât veren bir Müslüman için söylenebilecek yargı.</p></div><ol class=\"sv-s\"><li><b>Zekâtın arkasındaki düşünce</b> Malın gerçek sahibi Allah’tır; zenginin malında fakirin hakkı vardır. Zekât veren bunu bilerek verir.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Mülkünde başkalarının hakkı olduğunun farkındadır → doğru.</td></tr><tr><td>B</td><td>Zekât kibir değil, şükür ve sorumluluk duygusu kazandırır.</td></tr><tr><td>C</td><td>Yardım dokunulmazlık sağlamaz.</td></tr><tr><td>D</td><td>İbadetin kolaylığı söz konusu değil.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Onların mallarında isteyen ve mahrum olanlar için bir hak vardır.” (Zâriyât, 19)</div><div class=\"sv-w\"><b>Tuzak:</b> B ve C zekâtın amacına ters düşen kibirli düşüncelerdir.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 12. soru"
 },
 "mebi-din-y07-13": {
  "t": "din-zekat",
  "a": "C",
  "o": 100099,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekât, sadaka, infak.</li></ul><b>İstenen</b><p>Üç kavramın ortak özelliği.</p></div><ol class=\"sv-s\"><li><b>Her birini sına</b> Zekât farz, sadaka ve infak ise genel olarak nafiledir → A ortak değil. Yalnız fitre ramazana bağlıdır → B ortak değil. Sadakayı herkes verebilir → D ortak değil.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Yalnız zekât farzdır.</td></tr><tr><td>B</td><td>Ramazana bağlı olan fitredir.</td></tr><tr class=\"ok\"><td>C</td><td>Üçü de paylaşma ve yardımlaşmayı ifade eder → ortak.</td></tr><tr><td>D</td><td>Sadaka ve infak zenginlere özgü değildir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Ortak özellik sorularında her şıkkı üç kavramın üçüne de uygula.</div><div class=\"sv-w\"><b>Tuzak:</b> A zekât için doğru olduğu için seçilebilir; ortak özellik değildir.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 13. soru"
 },
 "mebi-din-y07-14": {
  "t": "din-zekat",
  "a": "C",
  "o": 100100,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Mallarını Allah yolunda harcayıp ardından başa kakıp incitmeyenler için Rableri katında özel karşılık vardır… İyi bir söz ve bağışlama, arkasından eziyet gelen bir sadakadan daha iyidir.” (Bakara, 262-263)</li></ul><b>İstenen</b><p>Ayetlerde vurgulanan.</p></div><ol class=\"sv-s\"><li><b>Ayetlerin uyarısı</b> Yardım ettikten sonra başa kakmak, incitmek sevabı yok eder. Yardım edilenin gururu kırılmamalıdır.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Mahremiyet (gizlilik) bu ayetlerin vurgusu değil.</td></tr><tr><td>B</td><td>Doğru ama ayetin özel vurgusu değil.</td></tr><tr class=\"ok\"><td>C</td><td>Yardım edilen kişiyi incitecek davranışlardan kaçınmak → vurgu.</td></tr><tr><td>D</td><td>Teşvik konusu geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> “Başa kakmak” ve “eziyet” sözcükleri cevabın anahtarıdır.</div><div class=\"sv-w\"><b>Tuzak:</b> A, gizli sadaka ayetiyle (Bakara 271) karışır.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 14. soru"
 },
 "mebi-din-y07-15": {
  "t": "din-zekat",
  "a": "C",
  "o": 100101,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekâtın sözlük anlamlarından biri “arınma”dır ve bireyin manevi gelişimiyle ilgilidir.</li><li>I. Kalbi cimrilik ve bencillikten temizlemek. II. Yardım edilenlerin takdirini kazanmak. III. Maldaki kul hakkını ayıklayıp kazancı temizlemek.</li></ul><b>İstenen</b><p>Arınmayı temsil eden ifadeler.</p></div><ol class=\"sv-s\"><li><b>Arınma iki yönlüdür</b> Kalbin arınması (cimrilikten, bencillikten) ve malın arınması (içindeki fakirin hakkını vererek).</li></ol><table class=\"sv-c\"><tr><td>I</td><td>Kalbin arınması → temsil eder.</td></tr><tr><td>II</td><td>Takdir kazanmak arınma değil, gösteriş beklentisi olur.</td></tr><tr><td>III</td><td>Malın arınması → temsil eder.</td></tr><tr class=\"ok\"><td>C</td><td>I ve III.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Zekât hem kalbi hem malı temizler.</div><div class=\"sv-w\"><b>Tuzak:</b> II olumlu bir sonuç gibi görünür ama arınmayla ilgisi yoktur, hatta niyeti bozar.</div><div class=\"sv-a\">Cevap <b>C</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 15. soru"
 },
 "mebi-din-y07-16": {
  "t": "din-zekat",
  "a": "A",
  "o": 100102,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekât oranı onda bir olan mal soruluyor.</li></ul><b>İstenen</b><p>Zekât oranı {{1|10}} olan mal.</p></div><ol class=\"sv-s\"><li><b>Oranları hatırla</b> Masrafsız (yağmurla) sulanan toprak ürünleri {{1|10}}; masraflı sulanan {{1|20}}. Nakit para {{1|40}}. Küçükbaş: 40 koyunda 1. Büyükbaş: 30 sığırda 1 dana.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Masrafsız tarım ürünleri → {{1|10}}.</td></tr><tr><td>B</td><td>Nakit para → {{1|40}}.</td></tr><tr><td>C</td><td>Küçükbaş → 40’ta 1.</td></tr><tr><td>D</td><td>Büyükbaş → 30’da 1.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Öşür = onda bir; masraf olursa yirmide bir.</div><div class=\"sv-w\"><b>Tuzak:</b> “Toprak masrafı yapılmadan” ayrıntısını kaçırırsan {{1|20}} ile karıştırabilirsin.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 16. soru"
 },
 "mebi-din-y07-17": {
  "t": "din-zekat",
  "a": "A",
  "o": 100103,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>“Sadakaları açık verirseniz ne güzel! Şayet onu yoksullara verirken gizlerseniz bu sizin için daha da hayırlıdır…” (Bakara, 271)</li></ul><b>İstenen</b><p>Öğrenciye sadaka veren kişinin dikkat etmesi gereken.</p></div><ol class=\"sv-s\"><li><b>Gizli vermenin hikmeti</b> Yardım alanın onuru korunur, verende gösteriş olmaz.</li></ol><table class=\"sv-c\"><tr class=\"ok\"><td>A</td><td>Muhatabın onurunu zedelemeden yardım → ayetin mesajı.</td></tr><tr><td>B</td><td>Başarı kontrolü ayetle ilgisiz.</td></tr><tr><td>C</td><td>Duyurmak, gizli vermenin tam tersi.</td></tr><tr><td>D</td><td>Tek seferde vermek ayette geçmez.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Gizli sadaka hem verenin ihlasını hem alanın onurunu korur.</div><div class=\"sv-w\"><b>Tuzak:</b> C, “açık verirseniz ne güzel” kısmına dayanır; ama ayet gizli vermeyi daha hayırlı sayar.</div><div class=\"sv-a\">Cevap <b>A</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 17. soru"
 },
 "mebi-din-y07-18": {
  "t": "din-zekat",
  "a": "D",
  "o": 100104,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Tevbe 60: Zekâtlar fakirler, miskinler, zekât memurları, kalpleri İslam’a ısındırılacaklar, köleler, borçlular, Allah yolunda olanlar ve yolda kalmışlar içindir.</li></ul><b>İstenen</b><p>Ayetin cevap olduğu soru.</p></div><ol class=\"sv-s\"><li><b>Ayetin içeriği</b> Ayet bir liste sayıyor: zekât alacak kişiler.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>Miktar ayette yok.</td></tr><tr><td>B</td><td>Zaman ayette yok.</td></tr><tr><td>C</td><td>Şartlar ayette yok.</td></tr><tr class=\"ok\"><td>D</td><td>Kimlere verilir → ayetin cevabı.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Tevbe 60 = zekâtın verileceği 8 sınıf.</div><div class=\"sv-w\"><b>Tuzak:</b> Ayetteki “farz olarak” ifadesi C’yi çağrıştırabilir; ama ayet şart değil kişi sayıyor.</div><div class=\"sv-a\">Cevap <b>D</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 18. soru"
 },
 "mebi-din-y07-19": {
  "t": "din-zekat",
  "a": "B",
  "o": 100105,
  "s": "<div class=\"sv\"><div class=\"sv-g\"><b>Verilen</b><ul><li>Zekâtla yükümlü olmak için gereken asgari zenginlik ölçüsü soruluyor.</li></ul><b>İstenen</b><p>Bu ölçünün adı.</p></div><ol class=\"sv-s\"><li><b>Kavramlar</b> <b>Nisap:</b> zekât için gereken asgari zenginlik (ör. 80,18 g altın). Öşür: toprak ürünlerinin zekâtı. İnfak: Allah yolunda harcama. Sadaka: her türlü iyilik.</li></ol><table class=\"sv-c\"><tr><td>A</td><td>İnfak harcamadır.</td></tr><tr class=\"ok\"><td>B</td><td>Nisap → asgari zenginlik ölçüsü.</td></tr><tr><td>C</td><td>Öşür toprak ürünü zekâtıdır.</td></tr><tr><td>D</td><td>Sadaka her türlü iyiliktir.</td></tr></table><div class=\"sv-t\"><b>Püf nokta:</b> Nisap = zekâtın alt sınırı.</div><div class=\"sv-w\"><b>Tuzak:</b> Öşür de zekâtla ilgili bir terim olduğu için karıştırılabilir.</div><div class=\"sv-a\">Cevap <b>B</b></div></div>",
  "lb": "MEB Yaprak Test 7 · 19. soru"
 }
});
